export default [{"id":808,"question":"\"قراءة الفاتحة وتلاوة القرآن في المقابر\" مسألةٌ اختلف فيها الناس، ومنهم مَن ينسب صحَّة جوازها إلى بعض الأئمة: كشيخ الإسلام محمد بن عبدالوهاب في جواز ذلك، فما القول الصحيح في هذه المسألة؟","title":"حكم قراءة الفاتحة وتلاوة القرآن في المقابر","answer":"الجواب: القبور ما هي محل قراءة قرآنٍ، وليست محلًّا للصلاة، ولكنها محلّ للسلام والعبرة والذكرى، فيُسلم عليهم للتذكر والاعتبار والدعاء لهم بالرحمة والمغفرة، ولا يُصلَّى عندهم، ولا يقرأ عندهم، وما جاء في هذا من الأخبار والأحاديث كله لا صحَّة له، وما ورد في كتاب \"تمني الموت\" المنسوب للشيخ محمد بن عبدالوهاب من ذلك هو أمرٌ مشكوكٌ فيه، فالكتاب هذا غير معروفٍ عن الشيخ، وليس من مُؤلَّفاته فيما نعلم، وإنما غلط فيه مَن ظنَّ أنه من مؤلفاته، وليس معروفًا بين علماء الدعوة، ولا بين أحفاد الشيخ، ولم نسمع عنه إلا في هذه الأيام القليلة، فهو مشكوكٌ في نسبته إليه، والذي يظهر ونعلم من سيرته أنه ليس صحيحًا نسبته إليه، وليس من مُؤلفاته، وإنما غلط مَن ظنَّ أنه من مؤلفاته: إما لأنه ظنَّ أنَّ الخطَّ خطه، أو لأسبابٍ أخرى.\nثم على فرض أنه من مؤلفاته: فهو وغيره يُؤخذ من قوله ويُترك، ما وافق الحقَّ أُخذ، وما خالفه تُرك، سواء كان الشيخ محمد بن عبدالوهاب، أو شيخ الإسلام ابن تيمية، أو ابن القيم، أو غيرهم، ليس واحدٌ منهم معصومًا، فإذا غلط واحدٌ منهم في مسألةٍ وجب الأخذ بالدليل، وترك ما غلط فيه، مثل غيره من العلماء، ليس هذا خاصًّا بأحدٍ دون أحد، فالأئمة الأربعة والصحابة والتابعون وغيرهم إنما يُؤخذ من أقوالهم ما وافق الحقَّ، وما خالف الحقَّ من أقوالهم لم يُؤخذ به، وإن كان القائل عظيمًا: كأفراد الصحابة، وأفراد الأئمة الأربعة، وأشباه ذلك، مثلما قال مالكٌ رحمه الله: \"ما منا إلا رادٌّ ومردودٌ عليه، إلا صاحب هذا القبر\" يعني: الرسول ﷺ، ومثلما قال الشافعيُّ رحمه الله: \"أجمع الناسُ على أنَّ مَن استبانت له سنةُ رسول الله ﷺ لم يَجُزْ له أن يدعها لقول أحدٍ من الناس\"، وهكذا قال أبو حنيفة رحمه الله: \"إذا جاء الحديثُ عن رسول الله ﷺ فعلى العين والرأس، وإذا جاء عن الصَّحابة فعلى العين والرأس، وإذا جاء عن التابعين فهم رجالٌ ونحن رجالٌ\" يعني: كلٌّ يلتمس الحقَّ بدليله، وهكذا يقول أحمد رحمه الله لما سُئل: هل نأخذ بقولك؟ قال: \"لا تُقلدني، ولا تُقلد مالكًا، ولا الشافعي، وخذ من حيث أخذنا\"، وقال: \"عجبتُ لقومٍ عرفوا الإسنادَ وصحَّته –يعني: إلى النبي ﷺ- يذهبون إلى رأي سفيان -يعني: الثوري- والله يقول: فَلْيَحْذَرِ الَّذِينَ يُخَالِفُونَ عَنْ أَمْرِهِ أَنْ تُصِيبَهُمْ فِتْنَةٌ أَوْ يُصِيبَهُمْ عَذَابٌ أَلِيم [النور:63]\"، فإذا كان مَن أخذ بقول الثوري الإمام المشهور إذا كان مخالفًا للنص يُخشى عليه الفتنة؛ فكيف بمَن دون الثوري بمراتب؟!\nفالمقصود أنَّ أقوال أهل العلم يُحتجُّ لها، ولا يُحتجُّ بها على السنة وعلى الشرع، بل تُعرض أقوال العلماء على الكتاب والسنة، فما وافق الكتابَ والسنةَ فهو الحقُّ، وما خالفها رُدَّ على قائله، وإن كان كبيرًا، وإن كان عظيمًا؛ لأن قول الله أعظم، وسنة رسول الله أعظم.\nوقد صحَّ عن رسول الله عليه الصلاة والسلام أنه قال: اجعلوا من صلاتكم في بيوتكم، ولا تتَّخذوها قبورًا، فإن الشيطان يفرُّ من البيت الذي تُقرأ فيه سورة البقرة، فبين عليه الصلاة والسلام أن القبور ما هي محل صلاةٍ، ولا محل قراءةٍ، وإنما الصلاة في البيوت، والقراءة في البيوت، كما تكون في المساجد: اجعلوا من صلاتكم في بيوتكم، ولا تتَّخذوها قبورًا يعني: لا تجعلوها بمثابة القبور لا يُصلَّى فيها، ولا يُقرأ فيها.\nس: لو مثلًا قال لك: إن قراءة القرآن في المقابر دعاء، فما واجب الردّ عليه؟\nالشيخ: ليس دعاءً، الدعاء تقول: اللهم اغفر لهم، وارحمهم، ما هو تقرأ القرآن.\nس: يعني: ردّ عليك وقال لك: إنَّ الفاتحة دعاء؟\nالشيخ: لا، ما هي بدعاء، الدعاء: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6]، تطلب ربك للحيِّين، أما الميتين فماتوا، ما عاد في هدايةٍ، ليس لهم إلا ما قدَّموا.","link":"https://binbaz.org.sa/fatwas/20837/حكم-قراءة-الفاتحة-وتلاوة-القران-في-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0634حكم قراءة الفاتحة وتلاوة القرآن في المقابر؟ابن باز فتاوى المحاضرات.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":833,"question":"ما حكم غرس الأشجار على القبور؟","title":"ما حكم غرس الأشجار على القبور؟","answer":"الجواب: غرس الأشجار على القبور بدعة..؛ لأن النبي ﷺ لم يغرسها على القبور، وإنما غرس على قبرين أطلعه الله على تعذيبهما: أحدهما كان يمشي بالنَّميمة، والآخر كان لا يستتر من البول، فقطع... جريدة، وقال: لعله يُخفف عنهما ما لم تيبسا، ولم يفعل هذا في قبور المسلمين في البقيع، ولا أهل مكة، ولا في غير ذلك...، فلا يُشرع هذا، وهو بدعة.","link":"https://binbaz.org.sa/fatwas/20857/ما-حكم-غرس-الاشجار-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0652حكم غرس الأشجار على القبور؟ ابن باز فتاوى المحاضرات.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":891,"question":"نرى كثيرًا من الناس يضعون على القبور أجزاء من الخشب والحديد، وبعضهم يضع بلاطًا مُميزًا في منتصف القبر، ويدَّعون أنها علامة، فهل يجوز وضع مثل هذه العلامات؟ وهل يجوز وضع علامة على القبر؟","title":"ما حكم وضع علامات على القبر؟","answer":"الجواب: وضع العلامة جائزٌ: حجر، أو لوح، أو عظم، أو حديدة، أو شيء مما يُعلَّم به القبر؛ لا بأس، قد علَّم النبيُّ ﷺ قبر عثمان بن مظعون بعلامةٍ ، ونصَّ العلماء على ذلك، لكن بشرط ألا يكون في ذلك بناء ولا غلو، بل علامة تُوضَع في القبر، وليس فيها كتابة، لا يكتب على القبور..... لا كتابة، ولا وسم القبيلة؛ لأنها كتابة.","link":"https://binbaz.org.sa/fatwas/20927/ما-حكم-وضع-علامات-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0722ما حكم وضع علامات على القبر؟ ابن باز فتاوى المحاضرات.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":1369,"question":"لكل يوم يموت للناس ميت ويجتهد الوُّعاظ في وعظ الناس عند دفنهم حول القبر، ثم يأتي يجتهد شباب هداهم الله أو مشيب وينكرون عليهم ويقولون هذه بدعة، فأصل مشروعيتها ما هو؟","title":"ما دليل مشروعية التذكير عند القبور؟","answer":"الجواب:\nالتذكير عند القبور فعله النبي ﷺ لحديث علي في الصحيحين كان جالسًا عند قبر فوعظ الناس وقال: ما منكم من أحد إلا وقد كتب مقعده من الجنة ومقعده من النار قالوا: يا رسول الله ففيم العمل؟ قال: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسروا لعمل أهل السعادة، وأما أهل الشقاوة فييسروا لعمل أهل الشقاوة، ثم تلا قوله تعالى: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى  [الليل:5-7] الآيات من سورة والليل إذا يغشى، ذكره ابن كثير عند تفسير هذه الآية. كذلك من حديث البراء بإسناد صحيح عند الترمذي وغيره أنه ﷺ كان جالسًا عند قبر فذَكَّر الناس، وذكر موت الإنسان وخروج روحه وصعوده إلى عليين إن كان مؤمنًا وروحه طيبة، وردها من السماء إذا كان روحها خبيثة. ولأن الناس عند القبر قلوبهم فيها رقة تتأثر بالوعظ والتذكير عند ذكر الموت وتكون صالحة لقبول الذكرى ذلك الوقت.","link":"https://binbaz.org.sa/fatwas/21462/ما-دليل-مشروعية-التذكير-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التذكير عند القبور.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":1992,"question":"وضع الوَرْد على القبور؟","title":"حكم وضع العلامة والوَرْد والكتابة على القبر","answer":"الجواب:\n\nمنكر لا يجوز، لا تطييبها ولا وضع الورود عليها.\nس: وضع علامة على القبر؟\nالشيخ: العلامة لا بأس بها، النبي ﷺ لما توفي عثمان بن مظعون علّم عليه حتى يزوره عليه الصلاة والسلام، إذا علم عليه بحجر أو خشب أو شبه ذلك لا بأس.\nس: الكتابة منهي عنها؟\nالشيخ: لا يجوز الكتابة، لا يُبنى عليها، ولا يقعد عليها، ولا يُكتب عليها، نهى الرسول ﷺ عن هذا كله.","link":"https://binbaz.org.sa/fatwas/22108/حكم-وضع-العلامة-والورد-والكتابة-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بعض الأحكام المتعلقة بالقبور.mp3","categories":["أحكام المقابر"]},{"id":3056,"question":"إنارة المقابر؟","title":"ما حكم إنارة المقابر؟","answer":"الجواب: إذا كان في الطريق حول الطريق ولا يُشَبُّ إلا عند الحاجة، لا بأس، جعله في الطريق أو في لمبة تحفظ أو يجيئون بسراج معهم للحاجة ما في شيء، المنهي عنه نَصْبُ السُّرُج فيها، أما عند الحاجة كونه يُشَبُّ عند الحاجة ثم بعد الدفن يُطفأ ما في شيء.","link":"https://binbaz.org.sa/fatwas/23216/ما-حكم-انارة-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إنارة المقابر.mp3","categories":["أحكام المقابر"]},{"id":3159,"question":"هل مِن الواجب خلع النّعال أثناء دخول المقابر؟","title":"هل يجب خلع النّعال أثناء دخول المقابر؟","answer":"الجواب: نعم، النبي ﷺ أمر بخلعها إلا مِنْ حاجة؛ شدة شمس، أو شَوْك، والحاجة تدعو إلى المرور، وإلا فليخلع، النبي ﷺ قال: يا صاحب السَّبْتِيَّيْن اخلع السَّبْتِيَّيْن السَّبْتِيَّيْن يعني النعلين.","link":"https://binbaz.org.sa/fatwas/23322/هل-يجب-خلع-النعال-اثناء-دخول-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خلع النعال أثناء دخول المقابر.mp3","categories":["أحكام المقابر"]},{"id":4311,"question":"بعض الناس عندما يحضر إلى المقبرة يقومون بالتذكير على الحاضرين؟","title":"هل يُستحب تذكير الحاضرين في المقبرة؟","answer":"الجواب: ما في بأس، التذكير ما يخالف، النبي ﷺ نصح الناس وهو في المقبرة وهو ينتظر الدفن، نصحهم، بحديث علي في الصحيحين وفي حديث البراء بن عازب في السنن، نصح إذا جلسوا ينتظرون نصحهم طيب.\nس: التذكير في المقابر هل هو سنة أو مستحب؟\nج: مستحب لفعل النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/24585/هل-يستحب-تذكير-الحاضرين-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تذكير الحاضرين في المقبرة.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":5287,"question":"هل يجوز وضع جريد النخل والزهور على القبور بحجة تخفيف العذاب عن صاحب القبر إذا كان يعذب كما فعل الرسول ﷺ؟","title":"ما حكم وضع جريد النخل على القبر؟","answer":"الجواب: هذا غير مشروع؛ لأن الرسول ما فعله إلا مع قبرين أطلعه الله على عذابهما فوضع عليهما جريدتين وقال: لعله يخفف عنهما مالم ييبسا، أما القبور الأخرى فلم يضع عليها شيئًا عليه الصلاة والسلام، وإنما وضع ذلك على قبرين أطلعه الله على عذابهما، وغيره لا يطلع على عذاب المقبورين ولا يعلم ذلك، فذلك من أمور الغيب لا يعلم ذلك الناس حتى يضع عليها جريدة، فلا يستحب لا جريد ولا نخل؛ لأن الرسول لم يضع ذلك على قبور أهل البقيع ولا قبور الشهداء، ولو كان سُنة وقُربة لفعله ﷺ، وفعله أصحابه .[1]","link":"https://binbaz.org.sa/fatwas/30928/ما-حكم-وضع-جريد-النخل-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 007.mp3","categories":["أحكام المقابر"]},{"id":5381,"question":"مَن زار المقبرةَ ورأى على أحد القبور رخامًا مكتوبًا عليه اسم الميت وتاريخ وفاته يُزيلها؟","title":"ما حكم إزالة الكتابات التي على القبور؟","answer":"الجواب: يُزيلها؛ لأنَّ الرسول نهى أن يُكتب على القبور، نهى أن يُكتب عليها، وأن يُبنى عليها، فإذا وجد على قبرٍ كتابةً يُزيلها. س: لكن إذا أزالها يمكن أن يُسبب له الأذى؟ ج: يرفع أمره إلى الهيئة، إذا كان يخشى شيئًا يرفع أمره إلى ولاة الأمور، يقول: ترى رأيت في المحل الفلاني كذا وكذا. س: نقل صاحب \"تلخيص الحبير\": أن الكتابة على القبور زيادة لا ثابتة؟ ج: لا، ثابتة، ثبت أنه نهى عن الكتابة على القبور. س: الكتابة إذا وضع أرقامًا؟ ج: كذلك تُزال الأرقام، كتابة تُفهم. س: والحكمة في النهي؟ ج: قد يكون سبب فتنةٍ بالشخص، ما حطّ عليه هذا إلا لأجل شيءٍ، وإذا سُمي كان كذلك قد يفتتن به؛ لأنه أمير، أو عابد، أو عالم، أو شيء. س: إذا وضع الشخصُ بنفسه ليعرف أباه؟ ج: لا، يحطّ علامةً، شيئًا: حجرًا، أو عودًا، أو خشبةً صغيرةً، أو شيئًا، مثلما علَّم النبيُّ على عثمان بن مظعون بحجرٍ. س: كذلك النَّهي عن الكتابة يعمّ جدار المقبرة المسور على المقبرة؟ ج: كله نعم.[1]","link":"https://binbaz.org.sa/fatwas/31118/ما-حكم-ازالة-الكتابات-التي-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/mnbr_004.mp3","categories":["أحكام المقابر"]},{"id":5810,"question":"هل يجوز حط [أي: وضع] علامة على القبر لمعرفة أنه طريق؟","title":"حكم وضع علامة على القبر","answer":"الجواب: لا بأس بوضع علامة على القبر، علامة حجر خاص، أو عظم، أو عود، أو شبه ذلك، علامة، يروى أنه -عليه الصلاة والسلام- علم قبر عثمان بن مظعون. فالحاصل: أنه لا بأس بالعلامة التي يعلمها لا لقصد التعظيم، بل علامة: إما حجرًا خاصًا، أو لبنة خاصة، أو حديدة خاصة، أو شبه ذلك؛ ليعلم به القبر. السؤال: وكتابة؟ الجواب: لا، كتابة لا.","link":"https://binbaz.org.sa/fatwas/1156/حكم-وضع-علامة-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_157.mp3","categories":["أحكام المقابر"]},{"id":5812,"question":"ما حكم الإسلام فيمن يبني البيوت في المقابر؟","title":"حكم بناء البيوت في المقابر","answer":"الجواب: المقابر لا يبنى فيها، بل يجب أن يزال البناء، وعلى الدولة، والمسؤولين في البلديات، وهيئة الأمر بالمعروف، والنهي عن المنكر، وعلى الأمراء أن يلاحظوا هذا. القبور يجب أن تصان، وأن تسور، وأن تحفظ، ولا يبنى فيها لا بيوت، ولا دكاكين، ولا غير ذلك، بل تبقى على الموتى، فهي دورهم وهي محلهم.","link":"https://binbaz.org.sa/fatwas/1142/حكم-بناء-البيوت-في-المقابر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_148.mp3","categories":["أحكام المقابر"]},{"id":5820,"question":"هل يجوز لي أن أبني على قبر والدي إن خفت عليه من الإهانة، مع أنه في محل ليس يحترم الأموات، ولا ينفع النصح فيهم؟","title":"هل يجوز البناء على القبر إن خاف عليه من الإهانة؟","answer":"الجواب: ليس لأحد أن يبني على قبر أبيه، ولا غير أبيه، يضعه مع أموات المسلمين، ويكفي، والحمد لله، وليس له أن يبني على قبر أبيه، ولا قبر جده، ولا غيرهما، مثل ما فعل الصحابة، ومن بعدهم دفنوا أمواتهم في المقابر، ولم يبنوا عليها شيئًا، هذا هو الواجب.","link":"https://binbaz.org.sa/fatwas/1139/هل-يجوز-البناء-على-القبر-ان-خاف-عليه-من-الاهانة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_145.mp3","categories":["أحكام المقابر"]},{"id":5840,"question":"إلى أي حد يكون ارتفاع القبر عن الأرض؟","title":"مقدار ارتفاع القبر عن الأرض","answer":"الجواب: المشروع شبر وما حوله، وقد رفع قبر النبي قدر شبر، وما يقارب ذلك، أما رفعه كثيرًا فهذا لا يجوز.","link":"https://binbaz.org.sa/fatwas/1162/مقدار-ارتفاع-القبر-عن-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_161.mp3","categories":["أحكام المقابر"]},{"id":7388,"question":"أقدم لسماحتكم هذه الوجيزة مستفتيًا عن حكم الإرشاد في المقبرة، وذلك أن يقوم شخص من بين الحضور في المقبرة، أو بيت الميت بالإرشاد والدعوة إلى الله، وإن كان جائزًا فما الدليل على جوازه من السنة، أفيدونا جزاكم الله خيرًا؟","title":"حكم الوعظ والإرشاد عند المقبرة","answer":"الجواب: الإرشاد مطلوب في جميع الأوقات، والنصيحة في جميع الأوقات ليس لها حد محدود، النصيحة والإرشاد مطلوب في المقابر، وفي البيوت، وفي المساجد، وفي المجتمعات، في الطائرة، وفي السيارة، وفي القطار، وفي المركبات الفضائية، وفي كل مكان، النصيحة مطلوبة في كل وقت. وثبت عن النبي ﷺ أنه كان ذات يوم في المقبرة عند قبر ينتظرون دفنه عند الميت، فشرع ينصحهم -عليه الصلاة والسلام- ويعلمهم، ويقول -عليه الصلاة والسلام-: إن الميت إذا حضره أجله؛ نزل إليه ملائكة بيض الوجوه إذا كان مؤمنًا بيض الوجوه معهم كفن من الجنة، وحنوط من الجنة، فيجلسون منه مد البصر، فإذا خرجت روحه وقبضها ملك الموت؛ لم يدعها في يده حتى يأخذوها منه، ويضعوها في ذلك الحنوط، وذلك الكفن ثم ذكر حال الكافر وروحه، والملائكة سود الوجوه من جهته إلى غير ذلك . ذكر في مجلس آخر أيضًا في مقبرة حين جاء ولم يتم حفر القبر، ولم يدفن الميت، جلس مع أصحابه، وقال لهم وهو عند القبر: ما منكم من أحد إلا وقد كتب مقعده من الجنة ومقعده من النار قالوا: يا رسول الله ففيم العمل إذا كانت مقاعدنا معلومة من الجنة والنار ففيم العمل، يعني: فلماذا نعمل؟ ألا نتكل على كتابنا، وندع العمل؟ فقال -عليه الصلاة والسلام-: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسرون لعمل أهل السعادة، وأما أهل الشقاوة فييسرون لعمل أهل الشقاوة، ثم تلا قوله تعالى:  فَأَمَّا مَنْ أَعْطَى وَاتَّقَى  ۝ وَصَدَّقَ بِالْحُسْنَى  ۝  فَسَنُيَسِّرُهُ لِلْيُسْرَى  ۝  وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى  ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10]  فهذا يدل على أن الإرشاد والنصيحة والتوجيه عند المقبرة أمر مطلوب، ولا بأس به؛ لأن الناس عند المقبرة عندهم قلوب مقبلة، وعندهم شيء من اللين لمشاهدة الميت، والمقابر، فهم حريون بأن يتأثروا، وهكذا في البيوت إذا عزى المصابين، إذا جاءهم وزارهم وعزاهم، يذكرهم ويعظهم، ويقول: هذه سنة الله في عباده، الموت حق، ومن لم يمت اليوم مات غدًا، الطريق ماشٍ، وينصح، ويقول لهم: أبشروا واصبروا وصابروا والله يقول: وَبَشِّرِ الصَّابِرِينَ [البقرة:155] وما أشبه ذلك من الوعظ، والتذكير. السؤال: أحد الإخوان قام وخطب فوق القبر، وكثير من الإخوان أنكروا عليه، وقالوا ما يجوز؟ الجواب: الذي نعلم أنه مشروع تذكير الناس على حسب الحال، إن كان المكان يعني المدة طويلة؛ بسط، وإن كان الناس مشغولين؛ خفف، لكن إذا كان الناس جالسين ينتظرون، والقبر لم يكمل، بعض الأحيان يكون القبر يحتاج إلى حفر، وإلى تحسين، وإلى إصلاح، فيجلسون، ويستمعون، وتارة قد يكون جهز كل شيء، فإذا ذكرهم؛ ولو قليلًا، ولو بكلمات قليلة؛ يكون أنفع، تأسيا بالنبي -عليه الصلاة والسلام-. السؤال: لكن يا شيخ فعل هذا جائز؟ الجواب: مشروع، ومن قال: لا، يراجع السنة هي حاكمة على الجميع.","link":"https://binbaz.org.sa/fatwas/3471/حكم-الوعظ-والارشاد-عند-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1775.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":7632,"question":"أيضاً سؤاله الأخير يقول: يوجد مقابر في اليمن، وعلى هذه المقابر أشجار، وقد مر عليها مئات السنين، لا أحد يأخذ منها؛ لأنهم يدعونها حق الأولياء المقبورين في هذه المقابر، وأنه من أخذ منها تتصور له حنش -يعني: يقصد بذلك ثعبان- كما يقولون، المطلوب يجوز.. أو يقول: إنه يعضه بنابه وأنه يخرج عليه من هذه الأشجار الذي على القبور، هل هذا صحيح، وما مدى صحة قطع الأشجار مع القبور؟","title":"حكم قطع الأشجار التي في المقابر","answer":"الجواب: كل هذا لا بأس به، لا بأس أن يأخذ الأشجار يقطعها، ولا بأس أن يأخذ من ثمارها إن كان فيها ثمرة كالسدر ونحوه، ولا بأس أن يقطعها ويستفيد منها إذا كان ما هي مملوكة لأحد، ولا في أرض مملوكة لأحد، إنما نبتت على المطر -مثلاً- فلا بأس أن تقطع وينتفع بها، ولكن إذا كان هناك فتنة تقع بهذا الشيء فينبغي أن لا يقدم على هذا إلا بمشاورة ولاة الأمور حتى لا تقع فتنة بينه وبين الناس، ولاة الأمور لهم التصرف، يشاورهم في قطعها لمصلحة المسلمين أو الفقراء أو ما أشبه ذلك، أما إذا كان لا يترتب على قطعها فتن ولا قتال ولا شرور وأحب الإنسان أن يقطعها ليستفيد منها وينتفع بها فلا بأس بذلك. \nأما قوله هنا: لحرمة القبور أو لكرامات الأولياء أو لكذا أو لكذا، هذا لا أصل له، أو أن من أخذ منها يصيبه حنش أو كذا فهذا من تلبيس الملبسين ولا أصل لهذا الشيء، فلا بأس أن تؤخذ وتقطع، ولا بأس أن تؤكل ثمارها إذا كان فيها ثمر، ولكن إذا كان قطعها قد يترتب عليه شيء من النزاع بينه وبين الناس أو القتال أو شيء من الفتن، فينبغي له أن لا يعجل في الأمور حتى يستشير أهل العلم أهل البصيرة أهل الهدى والاستقامة، وحتى يتفق مع ولاة الأمور، إما أمير البلد أو قاضي البلد، حتى يكون هذا على بصيرة وحتى لا تقع فتن بينه وبين الناس. نعم.","link":"https://binbaz.org.sa/fatwas/4686/حكم-قطع-الاشجار-التي-في-المقابر ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02508.mp3","categories":["أحكام المقابر"]},{"id":7639,"question":"أيضاً يقول الدكتور أحمد محمد طه من الطائف في رسالته: في مصر يبنون قبور فوق سطح الأرض، والأغنياء يبنون قبور، أما الفقراء فإنهم يدفنون في القبور القديمة، وكثيراً ما نشاهد أجسامهم من خلال القبور القديمة المهدومة، وأصبحت هذه عادة، وقد فكرت في بناء عدة قبور للفقراء في قريتي، ولكن ترددت؛ لأن السنة النبوية تحتم بدفن المسلم تحت التراب، وأقنعت الناس جميعهم بذلك، ولكنهم لم يستجيبوا، فهل لي أن أبني قبور للفقراء فوق سطح الأرض تمشياً مع العادة، أم لا تجوز هذه الحسنة؟ ولو بنيتها فهل لي أجر وثواب، أرجو إفادتي؟","title":"حكم بناء القبور فوق سطح الأرض","answer":"الجواب: السنة الحفر في الأرض للقبور أن يحفر فيها في الأرض وأن يعمق فيها إذا كانت الأرض صالحة، إذا كانت الأرض صالحة فالسنة أن يحفر فيها ويعمق الحفر إلى نصف الرجل فوق السرة.. فوق نصف الرجل يعني فوق العورة، وأن يكون فيها لحد، يجعل في جهة القبلة يكون فيه الميت هذه السنة، لكن لو كانت الأرض رديئة ما تماسك ضعيفة، فلا بأس أن تضبط بالبناء يحفر يضبط، يحفروا له حفراً ويضبطوه بالبناء أو بالألواح حتى لا ينهدم لا بأس بهذا عند الحاجة، أما البناء لا لا يبنى، يحفر لهم في الأرض ويضبط التراب بألواح أو بحجارة حتى يستقر التراب فوق ذلك. \nهذا هو السنة الدفن في الارض لا البناء، أما البناء ما ينبغي، إذا أراد الإحسان يحفر لهم حفراً مناسباً ويحيي السنة، لا يوافقهم على ما أحدثوا، بل المؤمن يحيي السنة ويدعو إليها ويصبر على ما في ذلك من المشقة، هكذا ينبغي للمؤمن. \nومن البلايا التي وقعت الآن في الناس وذلك من دهر طويل البناء على القبور، قبر يكون في الأرض أو في عاصرة الأرض ثم يبنى عليه قبة أو مسجد هذا من البدع ومن المنكرات العظيمة ومن وسائل الشرك، وهذا واقع بمصر والشام والعراق وغير ذلك، وقد كان واقعاً في مكة المكرمة وفي البقيع حتى أزال الله ذلك على يد الحكومة السعودية، وأحسنت في ذلك جزاها الله خيراً؛ لأنها أزالت البدع، والرسول ﷺ نهى عن ذلك نهى عن البناء على القبور وعن تجصيصها وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، هذا هو الواجب على حكام المسلمين أن يمنعوا البناء على القبور، وأن يمنعوا اتخاذ مساجد عليها والصلاة عندها، وألا يطاف بها، وألا تدعى من دون الله، ولا يستغاث بأهلها، كل هذا من المنكرات، لكن البناء من وسائل الشرك، أما دعاء الميت والاستغاثة بالميت وطلب المدد هذا من الشرك الأكبر، ومن عبادة غير الله  كما هو واقع في بعض البلاد، فهذا ينبغي الحذر منه وتحذير الناس منه. نعم.","link":"https://binbaz.org.sa/fatwas/4693/حكم-بناء-القبور-فوق-سطح-الارض ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_026/02606.mp3","categories":["أحكام المقابر"]},{"id":8512,"question":"أخونا يسأل سؤالًا طويلًا أرجو أن يتسع له بقية وقت هذه الحلقة، يقول: يقوم بعض الناس بوضع نقود ليست بسيطة على القبور بما يسمونها قبور الأولياء، ثم تجمع هذه النقود ويصرفونها في تعمير القباب وزخرفتها ووضع الأنوار عليها واستعمال مكبرات الصوت على تلك القباب لنشر دعايات ذلك الولي، كما يؤدون هناك صلاة الفريضة أحياناً داخل المقابر حول ذلك الولي، فما حكم الدين الإسلامي في مثل هذه الأفعال أفادكم الله؟","title":"حكم دفع الأموال لغرض بناء القباب على القبور وزخرفتها","answer":"الجواب: أولاً: التقرب بالنقود أو بالطعام أو بالخبز إلى القبور هذا منكر ومن الشرك الأكبر؛ لأنها تقرب إليهم وعبادة لهم، الصدقات يتقرب إليهم يرجو بهذا فضلهم وثوابهم وبركتهم مثل ما لو ذبح لهم، ومثل لو صلى لهم؛ لأنه إنما تقرب بذلك لأنه يرى أنهم يصلحون لهذا الأمر، وأنه يتقرب إليهم بالصدقات أو بالذبائح أو بغير ذلك حتى ينفعوه، حتى يشفعوا له، حتى يبرئوا مريضه، وحتى يعطوه الولد وإلى غير ذلك.\nوأما ثانياً: فاتخاذ القباب على القبور أيضاً منكر، لا يجوز البناء عليها مطلقاً، بل يجب أن تبقى مكشوفة ليس عليها بناء، لقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولما ثبت في الصحيح عن جابر  قال: نهى رسول الله ﷺ عن تجصيص القبور وعن القعود عليها، وعن البناء عليها فالرسول ﷺ نهى عن البناء عليها، ونهى عن الكتابة عليها، فالواجب أن لا يكتب عليها وأن لا يبنى عليها، لا قبة ولا غيره.\nثالثاً: الصلاة عند القبور لا تجوز، الرسول ﷺ لعن من اتخذها مساجد، وقال الرسول ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك رواه مسلم في الصحيح، فنهاهم أن يتخذوها مساجد، ومن صلى عند قبر فقد اتخذه مسجداً، ولو ما بنى عليه قبة، ولو ما بنى عليه مسجد، ما دام يصلي عند القبور أو بين القبور فإنه بهذا يتخذها مسجداً؛ لأن الرسول عليه السلام قال: جعلت لي الأرض مسجداً وطهوراً فمن صلى في محل اتخذه مسجداً؛ ولهذا لا يصلى في المحل النجس، ولا يصلى بين القبور، فإذا صلى عند القبور أو إلى القبر أو في طرف المقبرة كل هذا اتخاذ لها، فالواجب الحذر من ذلك.","link":"https://binbaz.org.sa/fatwas/6583/حكم-دفع-الاموال-لغرض-بناء-القباب-على-القبور-وزخرفتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12708.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":8975,"question":"هل يجوز قطع الأشجار المؤذية من المقابر؟","title":"حكم قطع أشجار المقابر المؤذية","answer":"","link":"https://binbaz.org.sa/fatwas/7133/حكم-قطع-اشجار-المقابر-الموذية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14608.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":9112,"question":"هل من السنة الوعظ في المقبرة لجمع المشيعين؟","title":"حكم وعظ المشيعين للجنازة في المقبرة","answer":"الجواب: إذا تيسير ذلك فهو حسن إذا تيسر وعظهم وتيسر من يصغي له ويستفيد فهو مستحب، بل ثبت عن النبي ﷺ أنه وعظ الناس في المقبرة لما أتوا إلى قبر ولما يلحد وجلس مع أصحابه ذكرهم عليه الصلاة والسلام وبين لهم حال العبد إذا وضع في قبره وسألوه عن القدر قالوا: وهل نعمل في أمر مضى أو في أمر مستأنف؟ فقال: في أمر مضى، فقالوا: يا رسول الله كيف العمل ونحن قد فرغ من أمرنا؟ فقال عليه الصلاة والسلام: اعملوا فكل ميسر لما خلق له، أما أهل السعادة فييسر لعمل أهل السعادة، وأما أهل الشقاوة فييسر لعمل أهل الشقاوة، ثم تلا قوله سبحانه: فَأَمَّا مَنْ أَعْطَى وَاتَّقَى ۝ وَصَدَّقَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْيُسْرَى ۝ وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى ۝ وَكَذَّبَ بِالْحُسْنَى ۝ فَسَنُيَسِّرُهُ لِلْعُسْرَى [الليل:5-10].\nالمقصود أنه ﷺ ذكرهم وتلا عليهم بعض الأحاديث عليه الصلاة والسلام، فإذا تيسر تذكير الحاضرين ووعظهم فلا بأس بذلك حسن إن شاء الله. نعم","link":"https://binbaz.org.sa/fatwas/7272/حكم-وعظ-المشيعين-للجنازة-في-المقبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_179/17906.mp3","categories":["الدعوة والدعاة","أحكام المقابر"]},{"id":10448,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع عبد الله الحارثي، الأخ عبدالله له ثلاثة أسئلة في أحدها يقول: في قريتنا قبور مرتفعة عن الأرض بمقدار متر أو مترين، وقد وجدناها على هذه الحال منذ سنين طويلة ولا نعلم لمن هذه القبور، ومنطقة المقابر يوجد بها حص يستفاد منه في البناء، فهل يجوز لنا أخذ بعض هذا الحص أم لا يجوز، جزاكم الله خيراً؟الشيخ: حرث؟المقدم: حص نوع من التربة التي يستفاد منها في البناء.","title":"حكم رفع القبور عن الأرض بمقدار متر أو مترين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالواجب في هذه المسألة الرجوع إلى المحكمة لإفادتكم بما يلزم في هذا الموضوع، وفي إمكان المحكمة أن تكتب إلي حتى ندرس الموضوع مع المحكمة ونعمل ما يلزم إن شاء الله.\nالمقدم: بارك الله فيكم، حفظكم الله وجزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8618/حكم-رفع-القبور-عن-الارض-بمقدار-متر-او-مترين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28101.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":10709,"question":"والدي سمع من العلماء: أنه لا يجوز البناء على القبور، وفي مقبرة قريبة منا توجد فيها قبور عليها بنايات من الذين يدعون بـالصوفية أنهم يقولون: إنهم يضروا وينفعوا ولا يضر ولا ينفع إلا الله ، ويزورها الناس يوم الجمعة وأيام الأعياد، هل ما فعل والدي على حق، أم ننهه عن ذلك جزاكم الله خيراً؟","title":"إزالة البناء على القبور واجب على الدولة والحكام","answer":"الجواب: البناء على القبور لا يجوز، والواجب إزالته، وعلى الدولة والحكام أن يزيلوه أما الأفراد فليس لهم أن يزيلوه، إلا بإذن حتى لا يكون اصطدام وفتنة بينهم وبين المسئولين، فعلى ولاة الأمور من الأمراء والقضاة وعلى العلماء أن ينكروا هذا المنكر وأن يزال؛ لأن الرسول ﷺ لعن من بنى المساجد على القبور، قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، ونهى عن تجصيص القبور والبناء عليها، فالواجب أن يزال البناء حتى تكون شامسة بارزة كالقبور في المدينة في عهد النبي عليه الصلاة والسلام، وحتى لا يغلى فيها، إذا بني عليها صار هذا من أسباب الغلو فيها، وعبادتها من دون الله وتعظيمها التعظيم غير الشرعي، فلا يبنى عليها لا قبة ولا مسجد ولا غير ذلك، وإذا وجد بناء يرفع الأمر إلى ولي الأمر المسلم، وإلى العلماء حتى يزال بطريقة شرعية ليس فيها فتنة ولا تعرض لمشاكل تضر المجتمع، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8893/ازالة-البناء-على-القبور-واجب-على-الدولة-والحكام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_343/34308.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":10855,"question":"يسأل سؤالًا آخر ويقول: البعض يذكر أن القبر يرفع عن الأرض بمقدار شبر، فهل هذا صحيح، أم لا؟ وما دليله؟ وإن زيد على شبر فما حكمه؟ وكيف نوفق بين ذلك وبين ما ورد عن علي  كما ورد في مسلم: \"هل أبعثك على ما بعثني عليه رسول الله ﷺ ألا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته\"؟","title":"مقدار ارتفاع القبر عن الأرض","answer":"الجواب:  نعم القبور لا بأس أن ترفع قدر شبر كما ثبت من حديث سعد بن أبي وقاص: \"أنه رفع قبره قدر شبر، وأن قبر النبي ﷺ كان كذلك\" والسر في ذلك لتعرف أنها قبور حتى لا تمتهن، وحتى لا توطأ، وحتى لا يجلس عليها، فإنها إذا سويت بالأرض قد تخفى معالمها، فإذا رفعت قدر شبر وما يقاربه فهذا يعفى عنه ومشروع؛ لتعرف أنها قبور، ولتصان ولا تداس. أما حديث علي وما جاء في معناه فالمراد به الإشراف الزائد على هذا، كأن يُبنى عليها مساجد، أو قباب، أو بنية هذه تزال، وإنما ترفع بترابها نفس التراب الذي أخرج من اللحد، هذا يجعل فوقه؛ لأنه إذا دفن بقي بعض التراب الذي إلى اللحد، وبعض التراب الآخر؛ لأنه لو كان مرصوصًا أولًا .... عظيمًا، ثم بعد ما أخرج يتراكم بعضه على بعض، ويبقى منه بقية إذا دفن الميت، فهذه البقية تجعل على القبر علامة على أنه قبر، وقد نهى النبي ﷺ أن يزاد على ترابه، فالتراب الذي بقي من الميت يكون هو المرفوع على محله علامة، على أنه قبر، ولا يؤتى بزيادة أخرى من تراب، أو لبن، أو حصى، أو غير ذلك، لا بل يكفي التراب، وتوضع النصايب علامة على أنه قبر في طرفيه علامة أنه قبر، ولا بأس أن يوضع عليه شيء من الحصباء لحفظ التراب ويرش بالماء لا بأس كل هذا لا بأس به. نعم. المقدم: الحمد لله الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9023/مقدار-ارتفاع-القبر-عن-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_356/35604.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":11386,"question":"من أسئلتها -سماحة الشيخ- تقول: ما حكم وضع الأشجار على القبر وذلك بقصد تماسك التربة وعدم انجراف القبر من شدة الريح وكذلك رشه بالماء أيضًا للحفاظ عليه من الانجراف؟","title":"حكم رش القبر بالماء ووضع الأشجار عليه لئلا ينجرف","answer":"الجواب:  لا بأس برشه ووضع الحصباء عليه، يوضع عليه حصباء تمسكه، أما الشجر فلا، لا حاجة إلى ذلك؛ لأنه قد يعتقد فيه شيء، أما نصب الجريدة الذي فعلها النبي ﷺ فكان في قبرين اطلع على عذابهما -عليه الصلاة والسلام- أما نحن فلا نعرف المعذب من غير المعذب، فلا يشرع لنا أن نجعل عليه جريد ولا شجر، ولكن إذا جعل عليه حصباء ورش بالماء فهذا حسن لأجل ضبط التراب.","link":"https://binbaz.org.sa/fatwas/9555/حكم-رش-القبر-بالماء-ووضع-الاشجار-عليه-لىلا-ينجرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29312.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":12680,"question":"يقول: في قريتنا مقبرة تقع على طريق الناس، فما هي نصيحتكم؟","title":"واجب المسلمين تجاه المقبرة الموجودة في طريق الناس","answer":"الجواب:  الواجب تسويرها حتى لا يطأها الناس، حتى لا يمتهنوها، تسور ويجعل لها باب للحاجة حتى لا يطأها الناس، وحتى لا يمتهنها الناس، وفي الإمكان الاتصال بالمحكمة حتى تقوم باللازم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10890/واجب-المسلمين-تجاه-المقبرة-الموجودة-في-طريق-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45819.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":12705,"question":"يقول في أيام العيد نضع على قبور الموتى جريدًا أخضر، هل لهذا أصل؟","title":"حكم وضع الجريد الأخضر على القبر","answer":"الجواب:  ليس له أصل، النبي ﷺ وضع الجريد على قبرين معذبين، وأطلعه الله على عذابها، قال: أما أحدهما فكان يمشي بالنميمة والعياذ بالله وأما الآخر فكان لا يستتر من بوله يعني: لا يتنزه من البول، ولم يضع على قبور الصحابة في البقيع، ولا في أحد، فدل ذلك على أن هذا خاص بالقبرين، فليس للإنسان أن يضع على القبور جريدًا، ولا زهورًا، ولا غير ذلك، لا في أيام عيد، ولا في غيرها، بل هذا منكر وبدعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10915/حكم-وضع-الجريد-الاخضر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45910.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13218,"question":"هذا السائل يسأل ويقول: ما حكم الشرع في القبور التي تعلو سطح الأرض، كالقبور التي تتكون من دورين، وهذا يكون بسبب ضيق المساحة المخصصة للقبور سماحة الشيخ؟","title":"حكم رفع القبور","answer":"الجواب:  الواجب أن تكون القبور في داخل الأرض، يحفروا يحفر في قبر نصف قامة ويدفن، هذا إذا استطاع، إذا تيسر ذلك، إما إذا كانوا في أرض جبلية ما يستطيعون فإنه يكوم حصى من هنا ومن هنا، ويدفن بينها، يوضع على الشق الذي دفنوا فيه شيء من الحجارة؛ حتى يغطى، وهذا جهدهم فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا أمكن الحفر؛ فإن السنة أن يحفر له في الأرض، وأن يدفن في الأرض، وألا يرفع عن الأرض إلا قدر شبر، وما حوله؛ حتى يعرف أنه قبر، وأما وضع أحجار، أو بناء على القبر من دون موجب؛ هذا لا يجوز. الرسول ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه، لكن إذا دعت الضرورة يجمع الحصى، ويكون مثل القبر، ويجعل الميت في وسطه، ويجعل فوقه الحجارة تغطيه، هذا إذا ما وجد مكانًا، كان في بلدهم -يعني- حجرية، ما يمكن الحفر، هذا فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] هذا جائز لهم؛ لأن الله -جل وعلا- يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. فإذا فرضنا ناسًا نزلوا في أرض حجرية ما فيها محل للدفن، ما فيها محل للحفر؛ فلهم أن يدفنوا بين الأحجار، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11495/حكم-رفع-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51217.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13499,"question":"يقول هذا السائل من الجزائر: ما حكم تزيين القبور؟","title":"حكم تزيين القبور والبناء عليها","answer":"الجواب: التزيين يختلف، إن كان المقصود كونه يجمع التراب عليها، ويجعل عليها النصائب هذا لا بأس، ما يسمى تزيين هذا هو المشروع، إذا دفن الميت يرفع قبره قدر شبر، بقية التراب توزع على قبره حتى يعرف أنه قبر، ويجعل النصائب على أطرافيه من اللبن؛ حتى يعرف أنه قبر؛ حتى لا يوطأ، ولا يمتهن. أما تزيينه بالجص، أو بالطيب يكب عليه، أو بالبناء عليه هذا منكر لا يجوز \"الرسول ﷺ نهى عن تجصيص القبور، ونهى عن القعود عليها، ونهى عن البناء عليها\" رواه مسلم في الصحيح، ونهى أن يكتب عليها أيضًا، فلا يكتب عليها، ولا تجصص، ولا يبنى عليها، لا مسجدًا ولا غيره ولا قبة، كل هذا بدعة. والذي يفعل في بعض الدول من البناء على القبور، واتخاذ القباب عليها، والمساجد هذا من البدع، من وسائل الشرك، لا يجوز هذا، والواجب على المسلمين ترك ذلك، والواجب على أمراء المسلمين أن يمنعوا هذا، وأن يزيلوا هذه الأشياء، يجب على جميع الدول الإسلامية أن تمنع هذا، تمنع البناء على القبور، وتزيل المساجد التي على القبور، أو الأبنية التي عليها، والقباب يجب أن تزال، وإذا كانت مساجد قديمة، ولكن دفن فيها ميتًا ينبش، إذا كانت المساجد هي القديمة، ولكن دفن فيها؛ ينبش، ويخرج منها إلى المقابر، يوضع في حفرة في المقابر، ويسوى عليه التراب كسائر القبور، ولا يجوز أن يبقى في المساجد قبور. أما إن كانت قبورًا قديمة، ولكن بني عليها؛ فالواجب هدم البناء، قبة أو مسجدًا يهدم ويزال، ولا يجوز؛ لأن هذا من وسائل الشرك، يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقالت له بعض أزواجه: يا رسول الله! إنا رأينا كنيسة في أرض الحبشة وفيها صور، قال -عليه الصلاة والسلام-: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله أخبر أنهم شرار الخلق ببنائهم على القبور، واتخاذ المساجد عليها والصور، وقال ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها وروى مسلم في صحيحه عن جابر  قال: نهى رسول الله أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه. فالواجب على علماء المسلمين في كل مكان، وعلى أمراء المسلمين في كل مكان إزالة هذا الشيء، ووعظ الناس، وتذكيرهم وتحذيرهم، وعلى ولاة الأمور أن يزيلوه بالقوة، يهدموا المسجد الذي على القبر، ويهدموا القبة التي على القبر، تكون القبور بارزة، ليس عليها قباب، ولا مساجد كما كانت في عهد النبي ﷺ في البقيع. وهكذا الآن في عهد الدولة السعودية، في البقيع، وفي غير البقيع مكشوفة، ليس عليها بناء، ولا مساجد، وهكذا كان الحال في عهد النبي ﷺ كانت القبور في البقيع، وفي غير البقيع، في مكة والمدينة وغيرها مكشوفة، وهكذا في عهد الصحابة -رضي الله عنهم وأرضاهم- حتى جاءت الرافضة، وغلت في القبور، وهكذا من شابههم من غير الرافضة. فالواجب الحذر، الواجب هدم المساجد التي على القبور، وهدم الأبنية والقباب التي على القبور، وأن تكون القبور مكشوفة، ليس عليها شيء، يزورها الناس للسلام عليهم، يزورها المسلمون للسلام فقط، يقول النبي ﷺ: زوروا القبور؛ فإنها تذكركم الآخرة وكان ﷺ يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين هذه السنة. المسلمون يزورون القبور، ويسلمون عليهم فقط، لا يسألونهم، ولا يدعونهم، ولا يتمسحون بالقبور، كل هذا من المنكر، من الشرك، دعاء الميت، والاستغاثة بالميت هذا من الشرك الأكبر، تقول: يا فلان اشفع لي أو انصرني أو اشف مريضي، سواء كان هذا عند النبي ﷺ أو عند البدوي أو عند الحسين أو عند فلان كل هذا شرك أكبر، فلا يجوز هذا أبدًا عند جميع المسلمين، لا يجوز أن تأتي القبر تقول: انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، لا قبور الأنبياء ولا غيرها، ولا يجوز أن تدعوه تقول: يا سيدي فلان! أو يا أبا فلان، أو يا رسول الله! انصرني، أو اشف مريضي. هذا من الشرك الأكبر، سواء كان ذلك مع الأنبياء، أو مع أهل البيت، أو مع غيرهم، ولا يجوز التمسح بالقبور، والتبرك بها، وإنما تزار فقط، يزورهم، يسلم عليهم فقط، تقول: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يرحم الله المستقدمين منا والمستأخرين، هكذا علم النبي أصحابه -عليه الصلاة والسلام- كان يعلمهم إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية هكذا روى مسلم في الصحيح، هكذا ذكر العلماء في بلوغ المرام، وفي منتقى الأخبار، وهكذا ذكر أهل العلم في كتب الحديث، وكتب الفقه بينوا هذا. فالواجب على علماء المسلمين نشر ذلك، وبيان ذلك للناس، يجب على العلماء أن يبينوا في المساجد، وفي خطب الجمعة، وفي غيرها، وفي المحاضرات، وفي المدارس، يعلموا الناس، يعلمونهم هذه الأمور حتى يكونوا على بصيرة، حتى يدعوا الغلو في القبور، حتى لا يبنوا عليها، حتى لا يتخذوا عليها المساجد، حتى لا يدعوها من دون الله .. لا يستغيثوا بها وبأهلها، المصيبة عظيمة الآن بهذه المسألة، في كثير من البلدان الإسلامية يبنى على القبور مساجد وقباب، ويدعى أهلها من دون الله، ويستغاث بهم، وينذر لهم، هذا هو الشرك، دعاؤهم من دون الله، والاستغاثة بهم، والنذر لهم هذا هو الشرك الأكبر، واتخاذ المساجد وسيلة لذلك، واتخاذ القباب وسيلة لذلك. فالواجب على الأمراء، أمراء المسلمين في كل مكان، يجب عليهم أن يزيلوا هذه القباب، وهذه المساجد التي على القبور، ويجب على العلماء أن ينبهوهم، وينصحوهم، ويذكروهم، إذا كانوا مسلمين؛ فعليهم أن يزيلوا ما حرم الله، إذا كان الوالي مسلمًا؛ فليتق الله، وليزل ما حرم الله من القباب والمساجد التي على القبور، وليمنع الناس من دعاء الموتى، والاستغاثة بهم، والنذر لهم، هذا لله وحده، هو الذي يدعى .. هو الذي ينذر له .. هو الذي يستغاث به، يقول: يا رب! اغفر لي، يا رب! انصرني، يا رب! اشف مريضي، يا رب! ارحم ضعفي، يا رب! ارزقني، يدعو ربه. أما الميت لا يدعى، لا الميت ولا الصنم ولا الكوكب ولا الجن، لا يدعون من دون الله، فالله هو الذي يدعى  فلا يجوز دعاء الأنبياء، ولا دعاء المؤمنين، ولا دعاء غيرهم، ولا دعاء الكواكب والنجوم، ولا دعاء الأصنام، ولا دعاء الجن، كل هذا لا يجوز، بل يجب إخلاص العبادة لله وحده يقول: يا رب! اغفر لي، يا رب! ارحمني، يا رب! انصرني، يا الله .. يا ذا الجلال والإكرام! اغفر لي وارحمني .. اشف مريضي .. ارزقني من فضلك. أما أن يأتي الميت يقول: ارزقني أو اشف مريضي! حتى ولو كان النبي محمد -عليه الصلاة والسلام- من جاء إلى قبره، أو بعيدًا عنه يقول: ارزقني يا محمد، أو انصرني، هذا الشرك الأكبر، أو يقول: يا سيدي! عبد القادر، أو يا سيدي الحسين، أو يا سيدي البدوي، أو يا سيدي فلان! انصرني، أو اشف مريضي، أو أنا في جوارك، أو أنا في حسبك، هذا هو الشرك الأكبر. يجب الحذر من هذه الأمور، ويجب على العلماء أن يبينوا للناس، وأن ينصحوهم، ويجب على الأمراء أمراء المسلمين أن يمنعوا هذا، وأن يزيلوا الأبنية التي على القبور، وأن تكون مكشوفة، ليس عليها مساجد، ولا قباب، هذا هو الواجب على المسلم؛ حماية لجناب التوحيد، وحرصًا على سلامة عقيدة المسلمين، ودعوة لهم إلى الحق، وأداءً لواجب الدعوة. نسأل الله أن يوفق ولاة أمر المسلمين لما يرضيه، ونسأل الله أن يعين العلماء على البلاغ والبيان، ونسأل الله أن ينصر بالجميع الحق، وأن يعيذ الجميع من مضلات الفتن، ولا حول ولا قوة إلا بالله! المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ، على هذا التوجية الطيب المبارك.","link":"https://binbaz.org.sa/fatwas/11810/حكم-تزيين-القبور-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_531/53102.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13610,"question":"السائل أخوكم في الله أبو علي له مجموعة من الأسئلة يقول في هذا  عندنا الأرض ترابية، فنقوم بحفرها لتسوية القبور، ونبنيها بطوب محروق، ما رأيكم سماحة الشيخ عبدالعزيز؟","title":"الأرض ترابية، فنحفرها لتسوية القبر، ونبنيها بطوب محروق فما الحكم؟","answer":"الجواب: الواجب أن تحفروا فقط، أما البناء لا تبنوا شيئًا؛ لأن الرسول ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه ولكن تحفرون حفرًا إلى نصف القامة مثلًا، ثم تجعل فيها لحد، ثم يدفن الميت يجعل في اللحد، وينصب عليه اللبن، ثم يهال عليه التراب، ويرفع عن الأرض قدر شبر بالطين حتى يعرف أنه قبر، ويجعل عليه النصايب في أطرافه لحفظ ترابه.  أما أن يبنى عليه شيء، لا يبنى عليه شيء، إنما يجعل التراب فوقه إذا نصب عليه اللبن، ينصب عليه اللبن نصبًا، ويسدد ما بين اللبن بالطين، وقصار اللبن، ثم يهال عليه التراب، ويرفع قدر شبر، التراب -تراب القبر- حتى يعرف أنه قبر.  أما أنه يبنى عليه شيء من داخل، أو من خارج؛ فلا يجوز، الرسول نهى عن تجصيص القبور، ونهى عن القعود عليها، ونهى عن البناء عليها -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11950/الارض-ترابية-فنحفرها-لتسوية-القبر-ونبنيها-بطوب-محروق-فما-الحكم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52804.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":13833,"question":"في آخر أسئلة هذا السائل يقول سماحة الشيخ: هل وضع الشجرة أو غصن الشجرة على القبر يخفف من العذاب كما وضعه النبي ﷺ؟ أم أنه خاص به ﷺ فقط؟ وضحوا لنا ذلك سماحة الشيخ.","title":"حكم وضع أغصان الشجر على القبر","answer":"الجواب: وضع الجريد على القبور غير مشروع، بل هو بدعة؛ لأن النبي ﷺ لم يفعل ذلك إلا في قبرين خاصين، فاطلع على عذابهما فوضع عليهما جريدتين، ولم يضع جرائد على قبور أهل البقيع ولا على غيرها، فدل ذلك على أن هذا الوضع خاص بالقبرين اللذين أطلعه الله على عذابهما خاصة، ولو كانت سنة لفعلها ﷺ في سائر القبور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12203/حكم-وضع-اغصان-الشجر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53712.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":13836,"question":"في آخر أسئلة هذا السائل يقول سماحة الشيخ: هل وضع الشجرة أو غصن الشجرة على القبر يخفف من العذاب كما وضعه النبي ﷺ؟ أم أنه خاص به ﷺ فقط؟ وضحوا لنا ذلك سماحة الشيخ.","title":"حكم وضع أغصان الشجر على القبر","answer":"الجواب: وضع الجريد على القبور غير مشروع، بل هو بدعة؛ لأن النبي ﷺ لم يفعل ذلك إلا في قبرين خاصين، فاطلع على عذابهما فوضع عليهما جريدتين، ولم يضع جرائد على قبور أهل البقيع ولا على غيرها، فدل ذلك على أن هذا الوضع خاص بالقبرين اللذين أطلعه الله على عذابهما خاصة، ولو كانت سنة لفعلها ﷺ في سائر القبور. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12203/حكم-وضع-اغصان-الشجر-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53712.mp3","categories":["البدع والمحدثات","أحكام المقابر"]},{"id":13869,"question":"هذا السائل حسين عوض من اليمن يقول في هذا  توفي والدي رحمه الله، فعند زيارتي لقبر والدي أشاهد بعض القبور عليها حجارة كبيرة وعليها اسم المتوفى، وليس على قبر والدي سوى التراب المركوم وحجارة صغيرة ليس عليها الاسم، فهل يجب علي أن أفعل مثل ما في هذه القبور من كتابة الاسم، ووضع التراب عليها؟","title":"حكم رفع القبور وكتابة اسم الميت عليها","answer":"الجواب: الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفالسنة في القبور أن لا ترفع قدر أكثر من الشبر، شبر فما يكون قربه، تمييزاً لها عن غيرها حتى يعرف أنها قبور، أما رفعها أكثر من ذلك فلا يجوز، وهكذا لا يجوز الكتابة عليها لا اسم صاحبها ولا غيره؛ لما ثبت عن النبي ﷺ: أنه نهى عن تجصيص القبور، وعن البناء عليها، وعن الكتابة عليها. فالبناء عليها لا يجوز، وهكذا تجصيصها؛ لأن هذا من وسائل الشرك؛ من وسائل الغلو فيها، وهكذا بناء المساجد عليها والقباب كله لا يجوز؛ لأنه من وسائل الشرك، وهكذا لا تجوز الكتابة؛ لأن الرسول نهى عنها عليه الصلاة والسلام، فلا يكتب عليها اسم الميت ولا غيره، وإذا وضع حجرًا للعلامة لا بأس، إنما توضع النصائب التي تحفظ التراب على أطراف القبر، أو يوضع عليه حصباء ويرش بالماء لحفظ التراب لا بأس، أما الحصى الكبار فلا حاجة إليه، إنما توضع حصاة للعلامة لا بأس. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12253/حكم-رفع-القبور-وكتابة-اسم-الميت-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_538/53801.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14218,"question":"في ثاني أسئلة هذا السائل يقول: ما حكم وضع جرائد النخيل أو الأراك على القبر في وقتنا الحاضر؛ لأن البعض -يا سماحة الشيخ- يحتج بأن وضع الجريد على القبر -أي: جريد النخل- على القبر هو خاص بالرسول ﷺ؛ لأنه علم بالعذاب الذي كان يعذب به صاحبا القبر؟ وجهونا في ضوء ذلك.","title":"حكم وضع جرائد النخيل على القبور","answer":"الجواب: هذا هو الصواب، ليس لأحد أن يضع الجريد ولا غيره على القبور؛ لأن الرسول ﷺ ما كان يضع على القبور شيئًا، قبور البقيع وغيرها ما كان يضع عليها شيئًا، إنما وضع الجريدة على قبرين أطلعه الله على عذابهما فوضع الجريدتين قال: لعله يخفف عنهما ما لم ييبسا ولم يضع الجريد على القبور الأخرى، فدل ذلك على أنه لا يشرع وضع الجريد ولا غير الجريد على القبور الأخرى؛ لأننا لا نعلم عذابهم، والله أطلع نبيه على عذاب القبرين فوضع الجريد لعله يخفف عنهما ما لم ييبسا، فليس لنا أن نشرع شيئًا جديدًا. نعم.","link":"https://binbaz.org.sa/fatwas/12669/حكم-وضع-جراىد-النخيل-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54819.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14243,"question":"سماحة الشيخ! بالنسبة للوعظ عند القبور ما رأيكم فيه؟","title":"حكم الوعظ عند القبور","answer":"الجواب: الوعظ لا بأس به، النبي وعظ عند القبر، جاء عنه ﷺ من حديث علي ومن حديث البراء بن عازب أنه وعظ الناس عند القبر وهم ينتظرون، وعظهم وذكرهم عليه الصلاة والسلام.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12700/حكم-الوعظ-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53014.mp3","categories":["الدعوة والدعاة","أحكام المقابر"]},{"id":14466,"question":"من أسئلة هذه السائلة من اليمن تقول: سماحة الشيخ جرت عندنا سيول عظيمة، مما أدى إلى جرف الأراضي، وأضرت ببعض عظام الموتى، وقامت بعض من النساء بجمع العظام ودفنها في الأرض، فهل على هؤلاء النسوة شيء؟","title":"حكم دفن النساء لعظام الموتى التي جرفها السيل","answer":"الجواب: إذا جرفت السيول المقبرة فعلى ولي الأمر والجهات المختصة أن ينظروا في ذلك، وأن يعيدوا العظام إلى مدافنها، ويسووها ويسوروا المقبرة حتى لا تصاب مرة أخرى، على ولي الأمر أو على المحسنين الذين يطلبون الأجر يعيدون العظام في محلها، كل عظام قبر في محلها، وإذا لم يعرفوا ذلك دفنوها في أي محل من المقبرة، وسووه بظاهر القبور على حالها حتى تعرف أنها قبور وتسور المقبرة بشبك أو ببناء حتى لا تمتهن، وحتى لا تدخلها السيول، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12945/حكم-دفن-النساء-لعظام-الموتى-التي-جرفها-السيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55418.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14622,"question":"إيهاب عبدالحميد مصري، ومقيم بالمملكة، له مجموعة من الأسئلة، يقول سماحة الشيخ في السؤال الأول: تجصيص القبر هل يجوز بناء القبر بالطوب الأحمر أو الإسمنت إذا كانت الأرض رخوة أو بها بلل، عندنا في بلادنا يكثر مثل هذا؟ أفتونا، مأجورين.","title":"حكم بناء القبور إذا كانت الأرض رخوة","answer":"الجواب: تجصيص القبور لا يجوز، والبناء عليها لا يجوز؛ لأن الرسول ﷺ نهى عن ذلك، نهى عن تجصيصها، والبناء عليها، ولا يجوز اتخاذ مساجد عليها؛ لأنه وسيلة الشرك، لكن إذا كانت الأرض رديئة غير متماسكة لا بأس أن تضبط بشيء مما يمسكها من ألواح أو خشب أو حجر شيء يضبط الأرض حتى يوضع فيها الميت، نعم.","link":"https://binbaz.org.sa/fatwas/13114/حكم-بناء-القبور-اذا-كانت-الارض-رخوة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_559/55910.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":14852,"question":"المستمع (م. ش. ع) من محافظة مطروح -برج العرب، بعث برسالة مطولة، ضمنها عددًا من الأسئلة، من بينها سؤال يقول فيه: بجوارنا الكثير من الأضرحة والقبور المرتفعة التي أوقدت عليها السرج، وتذبح له النذور من دون الله، ويحلف بأصحابها، والعياذ بالله، فإذا ما تحدثنا للناس، وبينا لهم بأن هذا شرك، وأن عليهم أن يتوبوا إلى الله، قالوا: بأنهم وجدوا آباءهم على هذه الحالة التي وصفت، فماذا نفعل إزاءهم؟ وجهونا ووجهوهم، جزاكم الله خيرًا.","title":"ما الواجب تجاه الأضرحة والقبور المرتفعة؟","answer":"الجواب: الواجب عليكم وعليهم إزالة الأبنية التي على القبور، وبقرها، وتركها ضاحية شامسة، كما كانت القبور في عهد النبي ﷺ في البقيع وفي غيره، وكما كانت القبور في بلاد أهل السنة والجماعة من قديم الزمان، ولا يجوز البناء عليها، ولا اتخاذ المساجد عليها؛ لأن الرسول نهى عن ذلك -عليه الصلاة والسلام-، وقال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقال جابر بن عبدالله الأنصاري : \"نهى رسول الله ﷺ عن تجصيص القبور، والقعود عليها، والبناء عليها\" ولا يجوز لأحد من الناس أن يدعوها من دون الله، أو يستغيث بأهلها، أو ينذر لهم، أو يذبح لهم، أو يطلبهم المدد، أو يتبرك بتراب قبورهم، كل ذلك منكر، ومن الشرك الأكبر، نعوذ بالله. فالواجب تنبيههم، وليس لهم حجة في تقليد آبائهم، هذه حجة المشركين، قال الله -جل وعلا- عن المشركين لما نهاهم الرسول ﷺ عن عبادة الأصنام قالوا: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُهْتَدُونَ [الزخرف:22] فهذه حجة باطلة، حجة ملعونة خبيثة، فلا يجوز الاحتجاج بها، هذه حجة الكفرة، إذا وجدت أباك على باطل لا تتبع أباك، أما إذا كان على حق؛ فالواجب الأخذ بالحق، سواءً كان عليه أبوك أو غير أبيك. وأما ما يفعله الناس اليوم عند القبور من الدعاء، والاستغاثة بأهلها، والذبح لهم، والطواف بقبورهم، كل هذا منكر عظيم، كل هذا من عمل أهل الشرك من عباد الأوثان. فالواجب على المسلم أن يحذر ذلك، وأن يحذره إخوانه، وينذرهم، والواجب على العلماء في كل مكان أن يحذروا الناس، وأن يرشدوهم، وأن يوضحوا لهم حقيقة التوحيد، وحقيقة الشرك، وأنه لا يجوز لأحد أن يدعو الميت من دون الله، ولا أن يستغيث به، ولا أن يذبح له، ولا أن يطلبه المدد، ولا أن يطوف بقبره، كل ذلك من الشرك الأكبر، كونه يطوف يتقرب إلى الميت بالطواف هذا شرك أكبر، أو يقول: يا سيدي، المدد المدد، أو الغوث الغوث، هذا من الشرك الأكبر، هذا من جنس عمل أبي جهل وأشباهه من عباد القبور، عباد الأصنام. فالواجب عليكم -أيها السائل- أن تستمروا في النصيحة والإنكار، وأن تطلبوا من العلماء أن ينبهوهم ويوضحوا لهم، ويرشدوهم، حتى يتركوا هذا الشرك، وحتى يزيلوا هذه الأبنية التي على القبور، وتبقى القبور ضاحية شامسة ليس عليها بناء، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/13349/ما-الواجب-تجاه-الاضرحة-والقبور-المرتفعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_644/nour_64406.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":15378,"question":"السائل صبري جعفر، مقيم بأبها، يقول: هل يجوز بناء المقابر فوق سطح الأرض، إذا كانت الأرض التي بها المقابر طينية أو زراعية؟ علمًا بأنه لو تم حفر حوالي نصف المتر، أو ربع المتر، سوف يظهر الماء، وليس هناك سوى المكان في هذه البلدة.","title":"ما حكم بناء القبور فوق سطح الأرض لأن الأرض طينية؟","answer":"الجواب: إذا كانت هكذا يجعل خشب أو ألواح، تحفر، ويجعل خشب، أو ألواح، يحول بين الماء وبين الميت، ويدفن في الأرض، ولا يبنى عليه؛ لأن الرسول ﷺ نهى أن يبنى على القبور، لكن يحفر القدر الذي لا يصل إلى الماء، يحفر ثم يجعل لوح تحته، أو أخشاب، أو شبه ذلك تمنع الماء، ثم يدفن الميت، ويهال عليه التراب، يوضع عليه اللبن، وعليه التراب، ولا يبنى عليه بناية، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13881/ما-حكم-بناء-القبور-فوق-سطح-الارض-لان-الارض-طينية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56709.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":16523,"question":"نعود في بداية هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع محمد حسن النهاري، الأخ محمد عرضنا بعض أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: في بلادنا توجد مقابر، ويوجد على هذه المقابر أعلاف، وحشائش تستعمل للبهائم، ولكن لا يذهب إلى هناك إلا النساء لحصاد الأعلاف، والحشائش، وكذلك توجد طرق في هذه المقابر تمر فيها النساء، وهو محرم على ما أعلم، وجهونا حول هذا الموضوع من ناحيتين: الناحية الأولى: الطرق. والناحية الثانية: وصول النساء إلى هناك من أجل الاستفادة من الحشائش، والأعلاف التي تنبت على هذه المقبرة، جزاكم الله خيرًا.","title":"حكم ذهاب النساء إلى المقابر من أجل الحشائش","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا حرج في ذهاب النساء إلى أخذ الحشائش التي في المقابر لعلف دوابهم، لا حرج في ذلك، المنهي عنه أن يزرن القبور، أما إذا أتين القبور لأخذ الحشائش التي فيها، والاستفادة منها مع الطرق المعينة لذلك؛ فلا بأس. والطرق التي وضعت في المقبرة للمرور بها للزائرين؛ فلا بأس إذا كانت ليس فيها قبور؛ فلا حرج، أما إن كان فيها قبور؛ فالواجب على الزائر يتخلل القبور، ولا يطأ على القبر، بل يمشي بين القبور، وهكذا المرأة إذا جاءت لأخذ الحشيش، تمشي بين القبور، ولا تطأ قبرًا، لا هي ولا الرجل، الجميع لا يجوز لهم امتهان القبور بالوطء عليها، ولكن يمشي بين القبور، وفي خلال الفرج التي بين القبور، حتى يأخذ حاجته، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15237/حكم-ذهاب-النساء-الى-المقابر-من-اجل-الحشاىش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75701.mp3","categories":["أحكام المقابر"]},{"id":16781,"question":"المستمع حسين ولد ميمني تاجي من الجمهورية الإسلامية الموريتانية، بعث برسالة إلى البرنامج، وضمنها سؤالين في أحد أسئلته، يقول: هل يجوز البناء على الميت كالبيت مثلًا؟ ولعله يقصد القبر سماحة الشيخ، جزاكم الله خيرًا.","title":"هل يجوز البناء على الميت مثل البيت؟","answer":"الجواب: البناء على القبور لا يجوز مطلقًا، بل ذلك من أسباب الشرك، ومن ذرائع الشرك، وقد قال -عليه الصلاة والسلام- في الحديث الصحيح: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وثبت في الصحيح من حديث جابر  قال: \"نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه\". فلا يجوز البناء عليه لا قبة، ولا حجرة، ولا مسجدًا، ولا غير ذلك، ولا أن يقعد عليه، ولا أن يجصص، ولا أن يجعل عليه الستور والأطياب، كل هذا منكر، ومن وسائل الشرك، فالواجب الحذر من ذلك، والواجب على المسلمين في كل مكان أن يحذروا هذا العمل السيئ الذي انتشر في بلدان كثيرة، ودول كثيرة. فالواجب هدم المساجد التي على القبور إذا كانت بنيت عليها، والقباب التي على القبور تهدم وتزال، هذا الواجب على الدول الإسلامية أن يزيلوها، وتكون القبور مكشوفة ليس عليها شيء.  أما إن كان القبر جديدًا هو الذي دفن في المسجد، والمسجد قبله، المسجد قديم؛ فإنه ينبش القبر، ويخرج إلى المقابر، يجعل مع المقابر، ولا يكون في المسجد، بل يجب أن ينبش، وأن ينقل رفاته إلى المقابر العامة، ويبقى المسجد سليمًا يصلى فيه.  أما إن كان القبر هو القديم، وبني المسجد عليه؛ فإنه يهدم المسجد، ولا يجوز بقاؤه، يجب على رؤساء الدول الإسلامية، المسؤولين أن يقوموا بهذا الواجب، وأن يمنعوا الناس من الشرك، وذرائعه، فإن دعاء الأموات، والاستغاثة بالأموات شرك أكبر.  وبناء المساجد على القبور بدعة، ومن أسباب الشرك، ولهذا قال ﷺ في الحديث الصحيح الذي رواه مسلم في الصحيح عن جندب بن عبدالله البجلي قال ﷺ: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك. ويقول ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد ولما قالت له أم سلمة، وأم حبيبة -رضي الله عنهما-: «إنهما رأتا في أرض الحبشة صورًا في بعض الكنائس، قال ﷺ في حق النصارى: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور ثم قال: أولئك شرار الخلق عند الله فأخبر أنهم شرار الخلق بسبب أعمالهم، وهي البناء على القبور، واتخاذ الصور عليها. فالواجب على الحكومات الإسلامية، وعلى جميع العلماء أن يسعوا في إزالة هذه الأبنية التي على القبور: من مساجد، وقباب، وغيرها، وأن تكون القبور بارزة مكشوفة، ليس عليها بناء، ولا مانع من رفع القبر قدر شبر، يرفع ترابه؛ حتى يعرف أنه قبر، يكون لحدًا، يكون له لحد، ويكون التراب الباقي يجمع على القبر؛ حتى يكون فوقه علامة على أنه قبر، وعليه نصايب، ويكون قدر شبر، ونحوه؛ حتى يعرف أنه قبر. أما البناء فلا يبنى عليه، لا مسجدًا، ولا غيره، ولا قبة، ولا غيرها، ولا يجوز أن يدعى صاحب القبر يقول: يا سيدي، أو يا فلان، يا أبا عبدالله، أو يا محمد، أو يا فلان! اغفر لي، أو انصرني، أو اشف مريضي، أو أنا في جوارك، ولا يقال: يا رسول الله، ولا يا أبا بكر، ولا يا سيدي البدوي، ولا يا سيدي الحسين، ولا يا سيدي عبدالقادر، ولا غيرهم، لا يجوز هذا كله، بل هو من الشرك الأكبر، دعاء الأموات، والاستغاثة بالأموات من الشرك الأكبر.  فلا يدعى الرسول ﷺ ولا غيره من الصحابة،  ولا من العلماء، بل هذا من الشرك الأكبر عند جميع أهل العلم من أهل السنة، والجماعة .. كانت الجاهلية يعظمون القبور، ويدعونها من دون الله، ويستغيثون بأهلها، فنهى الله عن ذلك، وحرم ذلك على المسلمين، قال : فَلا تَدْعُوا مَعَ اللَّهِ أَحَدًا [الجن:18] وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال : ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ[فاطر:13-14]، فسماه شركًا . فدعاء الأموات، وسؤالهم الشفاعة، أو النصر على الأعداء، أو شفاء المرضى، أو النذر لهم، أو الذبح لهم، كل هذا من الشرك الأكبر، ومن عبادة غير الله، والله سبحانه يقول: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ [الإسراء:23].. وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ [البينة:5] ويقول النبي ﷺ: الدعاء هو العبادة دعاء الميت عبادة، وشرك به بالله  نسأل الله السلامة والعافية، ونسأل الله أن يصلح أحوال المسلمين، وأن يمنحهم الفقه في الدين، وأن يصلح ولاة أمرهم، حتى يزيلوا ما وقع من الشرك، وذرائعه، ووسائله. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15534/هل-يجوز-البناء-على-الميت-مثل-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_762/nour_76213.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":16944,"question":"يسألن السائلات سماحة الشيخ عن وضع الأحجار فوق القبر، وتسمى النصاير، وهي وضع حجر فوق قبر الرجل واحدة، ووضع حجرين فوق قبر المرأة.","title":"حكم وضع حجر على قبر الرجل وحجرين على قبر المرأة","answer":"الجواب: يُوضع أحجارٌ تحفظ التراب، حجر أو حجرين الرجل والمرأة واحد سواء ما فيه تخصيص، ما في فرق بين المرأة والرجل، ما في ..... طرف القبر من فوق، ومن أعلى، ومن أسفل، لبنة أو حجر يحفظ التراب، أو علامة يعرف بها القبر، لا بأس. وأما تخصيص المرأة بحجرين، والرجل بحجر هذا لا أصل له، ولكن القبور واحدة، إذا جعل عليها حجرًا في أعلاها، أو في أسفلها لحفظ التراب، أو كب عليها حصباء تحفظ التراب كل هذا طيب.","link":"https://binbaz.org.sa/fatwas/15729/حكم-وضع-حجر-على-قبر-الرجل-وحجرين-على-قبر-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58617.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":17624,"question":"من المستمع الشيخ محمد مسعود أبو العباس من محافظة كفر الشيخ في جمهورية مصر العربية رسالة يقول فيها: يوجد عندنا مدافن على جبلٍ من الرمل، وكان المعتاد شق أخدود ووضع الميت فيه في تابوت من الخشب فجاء بعض الناس وأراد البناء ليجمع العائلة كلها، فقال البعض: إن هذا محرم غير شرعي، واستند لحديث عن النبي ﷺ ونهيه عن البناء على القبور وتجصيصها وقام الخلاف في ذلك، لكنا في انتظار ما نسمع من سماحتكم، جزاكم الله خيرًا.","title":"حكم البناء على القبور والدفن في أرض رملية","answer":"الجواب: البناء على القبور واتخاذ المساجد عليها والقباب أمر لا يجوز بنص النبي عليه الصلاة والسلام، ثبت في الصحيحين عن النبي ﷺ أنه قال: لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد، وقالت له أم سلمة وأم حبيبة أنهما رأتا في أرض الحبشة كنيسة ورأتا فيها صورًا كثيرة، قال أولئك -قال لهم النبي ﷺ-: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا وصوروه في تلك الصور ، ثم قال ﷺ: أولئك شرار الخلق عند الله فسماهم شرار الخلق.\nوفي الصحيح عن جابر  -صحيح مسلم، عن جابر - قال: \"نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه\".  فالقبور لا تجصص ولا يبنى عليها، ولا يبنى عليها مساجد، ولا يتخذ عليها قباب، بل هذا من وسائل الشرك، وهذا من عمل اليهود والنصارى، فالواجب الحذر منه. لكن إذا كانت الأرض رديئة يحفر فيها ويجعل فيها ما يمسك التراب من صندوق أو ألواح حتى لا تنهار على الميت أو حجارة حتى لا ينهار ويوضع الميت بينها، وإذا تيسر أرض صلبة جيدة يحفر فيها القبور ويكون فيها ألحاد من جهة القبلة، يوضع الميت في اللحد في جهة القبلة يكون هذا أفضل؛ لأن هذا هو الذي فعل بالنبي ﷺ، حفروا له وألحدوا له وجعلوه في اللحد، وهذا هو الأفضل. فإن لم يتيسر لأنها أرض رديئة يشق شق في الأرض ويجعل على جانبي الشق ما يحفظ التراب من ألواح أو حجارة من دون بناء، ثم يوضع الميت، ثم يوضع فوقه ألواح أو حجارة، ثم يرجم عليه التراب ويجعل عليه النصائب حتى يعرف أنه قبر، وتلتمس الأرض الطيبة ما هو بالأرض الرملية، إذا تيسر أرض طيبة يوضع فيها الميت حتى يحصر فيها، فإذا ما تيسر إلا أرض رديئة رملية يجتهدون في جعله في محل مناسب ثم يجعل فيه حجارة أو ألواح تحفظه عن التراب ثم يوضع الميت ثم يوضع فوقه حجارة تقيه التراب أو ألواح يقيه التراب، ثم يهال عليه التراب، إذا لم يتيسر أرض طيبة جيدة يحفر فيها ويكون فيها لحد ويوضع عليه اللبن، إذا تيسر هذا فهو السنة. أما إذا ما تيسر يكون شق في الأرض، يشق في الأرض ويوضع فيه الميت وتوضع على جانبيه وأطرافه الحجارة حتى تقيه التراب ثم يوضع فوقها حجارة كبيرة فوق الحجارة، تستره وتمنعه من التراب أو ألواح، وهذا هو المشروع في هذه الحالة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16553/حكم-البناء-على-القبور-والدفن-في-ارض-رملية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_843/nour_84306.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18308,"question":"من المستمع إدريس محمد، سؤال يقول فيه: هل تجوز الكتابة على القبور، أو وضع علاماتٍ مميزة؟ جزاكم الله خيرًا.","title":"حكم وضع علامة على القبر أو الكتابة عليه","answer":"الجواب: أما الكتابة على القبور فلا تجوز؛ لأن الرسول نهى عنها عليه الصلاة والسلام، لا تجوز الكتابة عليها، ولا البناء عليها، لا مسجد، ولا قبة، ولا غير ذلك، بل يعاد فيها ترابها، ويرفع القبر قدر شبرٍ تقريبًا، حتى يعرف أنه قبر، ولا يزاد عليه شيء، ولا يبنى عليه، ولا يكتب عليه، ولا يجصص، هكذا نهى الرسول ﷺ، نهى عن تجصيص القبور، وعن القعود عليها، والبناء عليها، والكتابة عليها، وأن يزاد عليها من غير ترابها؛ لأن هذا من أسباب الغلو. فالواجب ترك ذلك، أما التعليم فلا بأس، كونه يعلم بحجر خاص، أو بقطعة حديد، أو بعظم، أو لوح ما فيه كتابة، لا حرج، قد علم النبي ﷺ على قبر عثمان بن مظعون . فالحاصل أن التعليم بحجرٍ خاص، أو بلبنة، أو بلوح، أو شبه ذلك، لا بأس بهذا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17359/حكم-وضع-علامة-على-القبر-او-الكتابة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73205.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18309,"question":"سماحة الشيخ! يسأل هذا السائل ويقول: يشاهد بعد الدفن بعض الناس يضع على القبر علامتان من أحجار وعلى قبر المرأة ثلاث علامات وتسمى شاهد، فما حكم ذلك؟","title":"حكم وضع حجر أو حجرين على القبر ليُعرف","answer":"الجواب: لا بأس لتعريف القبر لا بأس، بما يعرف به قبر صاحبه، أو زوجة، أو أم، أو خالة، أو أب، أو عم، لا بأس، حجر أو حجرين، لا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/17360/حكم-وضع-حجر-او-حجرين-على-القبر-ليعرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91303.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18496,"question":"هذا السائل الذي رمز لاسمه بـ (م .م. ص) من اليمن يقول في سؤاله الأول: لقد طلب مني رجل أن أكتب على سطح قبر زوجته الذي هو مبني، يقول: طلب مني أن أكتب آية الكرسي بالطلاء، وكتبت الآية على سطح القبر، فهل عليَّ إثم في ذلك؟","title":"حكم كتابة آية الكرسي على القبر","answer":"الجواب: أولًا: القبر لا يجوز البناء عليه، الرسول ﷺ نهى أن يبنى على القبر، وأن يجصص، وأن يقعد عليه خرجه مسلم في الصحيح، فلا يجوز البناء على القبور؛ لأن البناء عليه قبة أو غيرها قد يسبب الغلو فيه، فالواجب أن يدفن ويرفع التراب عن الأرض قدر شبر علامة أنه قبر، ولا يبنى عليه شيء، لا قبة، ولا حجرة ولا غير ذلك، ولا يجوز الكتابة عليه؛ لأن الرسول ﷺ: نهى أن يكتب على القبر، وأن يبنى عليه، وأن يقعد عليه، ولا يجصص كلها نهى عنها النبي ﷺ والكتابة عليه قد تجر إلى الشر، قد يكتب عليه أنه كذا وأنه كذا وأنه كذا فيفتن الناس به، فلا تجوز الكتابة عليه لا قليلًا ولا كثيرًا. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17594/حكم-كتابة-اية-الكرسي-على-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78604.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18745,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: محمد (أ. س. د. ع) أخونا يناقش في قضية استمع إليها عبر حلقات هذا البرنامج، فيقول: أرجو عرض هذه المسألة على سماحة الشيخ عبد العزيز بن عبد الله بن باز، استمعت في إحدى حلقات (نور على الدرب) عن القراءة والصلاة والدعاء عند القبور، حيث أفتى سماحة الشيخ عبد العزيز بأن قراءة القرآن عند القبور لا تجوز، وطالب الشيخ بالدليل لمن يقول بجواز قراءة القرآن عند القبر.وقد اطلعت على كتاب الروح لابن قيم الجوزية، حيث وجدت الحديث التالي: قال الخلال، وأخبرني الحسن بن أحمد الوراق، حدثني علي بن موسى الحداد، وكان صدوقًا، قال: كنت مع أحمد بن حنبل ومحمد بن قدامة الجوهري في جنازة، فلما دفن الميت جلس رجل ضرير يقرأ عند القبر، فقال له أحمد: يا هذا، إن القراءة عند القبر بدعة، فلما خرجنا من المقابر، قال محمد بن قدامة لأحمد بن حنبل: يا أبا عبد الله، ما تقول في مبشر الحلبي؟ قال: ثقة، قال: كتبت عنه شيئًا؟ قال: نعم، فأخبرني مبشر عن عبد الرحمن بن العلاء بن اللجلاج عن أبيه أنه أوصى إذا دفن أن يقرأ عند رأسه بفاتحة البقرة وخاتمتها، وقال: سمعت ابن عمر يوصي بذلك، فقال له أحمد: ارجع، وقل للرجل يقرأ، انتهى.وقال الحسن الزعفراني: سألت الشافعي عن القراءة عند القبر؟ فقال: لا بأس بها، انتهى.وقد نقلت هذين النصين حرفيًا من كتاب الروح لابن قيم، وهناك أقوال كثيرة في هذا الكتاب تجيز القراءة والصلاة عند القبر، أرجو من سماحة الشيخ توضيح هذه المسألة، مأجورين -بإذن الله تعالى-، وفقكم الله، وجزاكم الله خيرًا.","title":"حكم الصلاة وقراءة القرآن عند القبور","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فقد اطلعت على ما ذكره السائل، وما نقله عن كتاب الروح، قد اطلعت عليه في كتاب الروح، ولكن ينبغي أن يعلم السائل أن الأدلة الشرعية منحصرة في كتاب الله وسنة رسوله ﷺ، وفي إجماع أهل العلم.  أما ما يتعلق بأقوال أفراد الصحابة فهي تعرض على الكتاب والسنة، والعبادات توقيفية، لا يجوز منها إلا ما أجازه الشرع، ولم يثبت عن رسول الله -عليه الصلاة والسلام-، ولا عن خلفائه الراشدين أنهم كانوا يقرؤون عند القبور، ولا يصلون عند القبور. أما ما فعله ابن عمر هذا اجتهاد منه ، وهكذا من فعله بعده من بعض السلف من باب الاجتهاد، والاجتهاد يخطئ ويصيب، والواجب هو عرض ما تنازع فيه الناس على كتاب الله، وعلى سنة رسوله -عليه الصلاة والسلام-، وعلى ما أجمع عليه أهل العلم. ومعلوم أن القراءة محلها البيوت والمساجد، وليس محلها المقابر، المقابر إنما تزار، ويدعى لأهلها، وهكذا الصلاة ليس محلها المقابر، وإنما محلها المساجد والبيوت، فكما أنه لا يصلى عند القبور، كذلك لا تتخذ محلًا للقراءة، لا عند الدفن، ولا بعد الدفن، لقول النبي ﷺ لعن الله اليهود و النصارى اتخذوا قبور أنبيائهم مساجد وقوله ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا. فدل ذلك على أن القبور ليست محلًا للصلاة، قال: لا تتخذوها قبورًا يعني: بترك الصلاة فيها، قال: صلوا في بيوتكم وهكذا قوله ﷺ: لا تصلوا إلى القبور، ولا تجلسوا عليها وكلها أحاديث صحيحة ثابتة عن رسول الله -عليه الصلاة والسلام-، وقال -عليه الصلاة والسلام- في الحديث الآخر: اجعلوا من صلاتكم في بيوتكم، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة. فالمقصود؛ أن المساجد والبيوت هي محل القراءة، وهي محل الصلاة، وليست المقابر محل صلاة، ولا محل قراءة، وإنما تزار للدعاء لأهلها؛ ولتذكر الآخرة، والزهد في الدنيا، وتذكر الموت، وكان -عليه الصلاة والسلام- إذا زار القبور يدعو لأهلها، يسلم عليهم، ويدعو لهم، وكان يعلم أصحابه إذا زاروا القبور أن يقولوا: السلام عليكم أهل الديار من المؤمنين والمسلمين، وإنا إن شاء الله بكم لاحقون، نسأل الله لنا ولكم العافية ولم يعلمهم أن يقرؤوا عندها القرآن. وقالت عائشة -رضي الله عنها-: كان -عليه الصلاة والسلام- إذا زار القبور يقول: السلام عليكم دار قوم المؤمنين، وإنا إن شاء الله بكم لاحقون، يرحم الله المستقدمين منا والمستأخرين، اللهم اغفر لأهل بقيع الغرقد. فلم يكن -عليه الصلاة والسلام- يقرأ عند القبور، ولم يكن يصلي عند القبور -عليه الصلاة والسلام-، والخير كله في اتباعه والسير على منهاجه -عليه الصلاة والسلام-، ولهذا قال -جل وعلا- في كتابه العظيم: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] ولم يكن خلفاؤه الراشدون يفعلون ذلك، وقد قال -عليه الصلاة والسلام-: عليكم بسنتي، وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ. وابن عمر له اجتهادات خالف فيها السنة، فمن ذلك: أنه كان يغسل داخل عينيه، وهذا خلاف السنة، وهذا من اجتهاده ، ومن ذلك: أنه كان إذا حج أو اعتمر يأخذ من لحيته ما زاد على القبضة، وهذا خلاف السنة، فقد قال -عليه الصلاة والسلام-: قصوا الشوارب، ووفروا اللحى، خالفوا المشركين خرجه البخاري في صحيحه، وقال -عليه الصلاة والسلام-: قصوا الشوارب، وأعفوا اللحى، خالفوا المشركين متفق على صحته، وكان يأخذ ماءً لأذنيه، والسنة أن تمسح الأذنان بماء الرأس. فالحاصل: أنه له اجتهادات  لا يوافق عليها من جهة السنة، فهكذا ما يروى عنه من القراءة عند القبر، وقت الدفن، هذا شيء اجتهد فيه  والسنة بخلافه. والإمام أحمد -رحمه الله- لما بلغه ذلك كان لاجتهاده -رضي الله عنه ورحمه- رأى أن يوافق ابن عمر، وأن يقر الكفيف على قراءته بعدما قال له: إنها بدعة، فقوله الأول هو الصواب، قول أحمد الأول هو الصواب، وهو الذي يوافق الأدلة الصحيحة الكثيرة عن رسول الله -عليه الصلاة والسلام-؛ ولأن القراءة عندها، والصلاة عندها وسيلة إلى عبادتها من دون الله؛ فالناس قد يظنون أن القراءة عندها لها مزية، ولها ثواب زائد، وهكذا الصلاة عندها، فيجرهم هذا إلى اتخاذها مساجد، وإلى دعاء أهلها، والاستغاثة بأهلها، والتوسل بأهلها، فيقع الشرك، ولا حول ولا قوة إلا بالله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17869/حكم-الصلاة-وقراءة-القران-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87501.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18753,"question":"يقول سماحة الشيخ: ما رأي سماحتكم في الوعظ عند القبور؟","title":"حكم الوعظ عند القبور","answer":"الجواب: الوعظ عند القبور مستحب إذا تيسر ذلك؛ لأن الرسول ﷺ وعظ عند القبور، ثبت من حديث علي  ومن حديث البراء بن عازب أن النبي وعظهم عند القبور -عليه الصلاة والسلام- وعظ الحاضرين عند القبور، فإذا حضر بعض أهل العلم ووعظ الناس عند القبر، عند انتظارهم الدفن، أو عند وقوفهم للدفن ذكرهم بالله حسن كله طيب.","link":"https://binbaz.org.sa/fatwas/17878/حكم-الوعظ-عند-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79007.mp3","categories":["أحكام المقابر","الدعوة والدعاة"]},{"id":18764,"question":"في آخر أسئلة هذا السائل، يقول: أستفسر عن الحكم الشرعي في نظركم سماحة الشيخ في البناء على القبور بالتفصيل.","title":"حكم البناء على القبور","answer":"الجواب: البناء على القبور محرم، لا يجوز البناء على القبر «النبي ﷺ نهى أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه»؛ لأنه من أسباب الغلو فيه، أن يحط عليه قبة، أو مسجدًا؛ هذا لا يجوز. أما كون المقبرة، عموم المقبرة تحاش بشيء حتى لا تمتهن بالدواب والناس لا بأس، هذا من باب صيانتها، أما أن يبنى على القبر تعظيمًا له، واحترامًا له؛ لأنه قبر فلان، أو قبر فلان؛ يوضع عليه قبة، أو مسجد؛ هذا لا يجوز، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17892/حكم-البناء-على-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79018.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":18994,"question":"من الأخ المستمع: محمد صبحي محمود كرم مدرس مصري رسالة بدأها على النحو التالي: بسم الله الرحمن الرحيم، الحمد لله، ونصلي ونسلم على نبينا ورسولنا محمد بن عبد الله، وآله ومن والاه.إلى العلماء الكرام، والقائمين على برنامج‎‏ نور على الدرب، السلام عليكم ورحمة الله وبركاته، أسأل الله لكم الجزاء الجزيل، وأن يهدي بكم وينفع، وأن يبلغكم غاية القصد المأمول، وأن يتوجكم بتاج القبول على ما تقدمونه للإسلام والمسلمين، إنه ولي ذلك والقادر عليه وبعد.نحن في معظم قرى ومدن مصر نعاني من مشكلة ضيق المساحة في القبور، حيث أنها محددة في أماكن معلومة، ولا يجوز ترك مكانها وخاصة في بلاد الدلتا أي البلاد البعيدة عن الصحراء، مما اضطر الناس لبنائها، وارتفاعها عن الأرض أكثر من المتر في بعض الأحيان؛ وذلك لدفن عدد من الموتى في كل قبر، فما حكم ذلك؟ وماذا نفعل إن أردنا أن نفعل الصواب في عدم بنائها فلا نجد الظروف التي تعيننا على ذلك؟ أفتونا مأجورين أثابكم الله، وجزاكم الله خيرًا.","title":"حكم رفع القبور لدفن أكثر من ميت","answer":"الجواب: أيها الأخ الكريم! نسأل الله لك المثوبة على دعواتك، ونسأل الله أن يتقبل منك دعواتك، وأن يثيبنا وإياك، وأن يجعلنا وإياك من عباد الله الصالحين، إنه خير مسئول. أما القبور فالواجب ألا تبنى هذا الواجب، وأن تحفر في الأرض، وتعمق هذا هو الواجب؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام من حديث جابر بن عبد الله الأنصاري رضي الله عنهما في صحيح مسلم \"أنه نهى عن تجصيص القبور، والبناء عليها\" ولعن اليهود والنصارى على اتخاذهم المساجد على القبور، وأخبر أنهم شرار الخلق بهذا العمل وهو البناء على القبور، واتخاذ المساجد عليها. فالواجب على أهل الإسلام في مصر، وفي غير مصر؛ الواجب عليهم أن يحفروا القبور في الأرض، وأن يعمقوها إلى نصف القامة تقريبًا حتى لا تظهر رائحتها، وحتى لا تحفرها الكلاب ونحوها، فإذا كانت البلد ليس فيها محل للحفر؛ لأنها صلبة حجرية، فلا حرج أن يدفن على ظهرها، ويحوط عليها؛ لأجل حفظها عن الكلاب وغيرها، وصيانتها؛ لأن الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]، لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا[البقرة:286]. فالبناء حينئذ لحفظها لا لتعظيمها، والغلو فيها، ولكن لحفظها عن ظهور الروائح الكريهة، وعن امتهانها، وعن تناول السباع لها، فلا حرج بقدر الحاجة، بقدر الحاجة فقط والضرورة، أما مع القدرة على الحفر فلا يجوز البناء لا متر ولا غيره، يجب أن تكون في الأرض، وأن تبين للناس، ترفع قدر شبر مثلًا تقريبًا، ترابها يكون على كل قبر ترابه، وعليه النصايب في أطرافه حتى يعلم يعرف أنه قبر، وإذا رش وجعل فيه بطحاء فذلك أفضل، هذا هو المشروع في القبور، لكن من لم يستطع ذلك في أن الأرض لا يمكن حفرها فإنه معذور بقدر الحاجة فقط. نعم. المقدم: جزاكم الله خيرًا، إذا كانت الأرض بعكس ذلك سماحة الشيخ، وكانت التربة تنهال، ولا تتماسك، فما هو الحل الذي يراه سماحتكم؟ الشيخ: إذا كانت الأرض ضعيفة لا يستطاع الحفر فيها؛ لضعفها، وانهيارها؛ يجعل ما يحفظ الميت من ألواح أو حجارة أو نحو ذلك مما يحفظ الميت، حتى لا ينهار به القبر، يفعل ما يستطيع المؤمن من ألواح أو أخشاب، أو حديد؛ المقصود الذي يستطيع به حفظ الميت، حتى لا ينهار به القبر. نعم. المقدم: والأمر متيسر في هذه الأزمنة والحمد لله؟ الشيخ: حسب الطاقة، حسب الطاقة، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ[التغابن:16]. المقدم: أحسن الله إليكم. الشيخ: نعم. المقدم: جزاكم الله خيرًا. الشيخ: وإياكم. المقدم: أرجو أن يتفهم إخواننا هذه الإجابة جيدًا، وأن يعيدوا الاستماع إليها أكثر من مرة فهي في غاية الوضوح، جزى الله الجميع كل خير. الشيخ: آمين، لا شك أن هذا مهم نسأل الله للجميع التوفيق. المقدم: اللهم آمين. الشيخ: نعم. المقدم: اللهم آمين. الشيخ: ثم نعيد أيضًا مرة أخرى. المقدم: أحسن الله إليك. الشيخ: التحذير من البناء على القبور الذي فعله اليهود والنصارى، لا يجوز أن يبنى عليها مساجد، ولا قباب ولا غير ذلك؛ لأن هذا البناء من أسباب الشرك بالله، والغلو كما فعله اليهود والنصارى، وفعله أشباههم من عباد القبور الذين ظنوا أن هذا مشروع، فاتخذوا المساجد على القبور، وغلوا فيها، واستغاثوا بأهلها، ونذروا لهم، وطافوا بقبورهم، وهذا هو البلاء العظيم، هذا الشرك الأكبر. يقول النبي ﷺ: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد، وقال عليه الصلاة والسلام لما أخبرته أم حبيبة وأم سلمة بكنيسة في بلاد الحبشة، وما فيها من الصور قال عليه الصلاة والسلام: أولئك إذا مات فيهم الرجل الصالح بنوا على قبره مسجدًا، وصوروا فيه تلك الصور، أولئك شرار الخلق عند الله حكم عليهم بأنهم شرار الخلق. فالواجب الحذر، وفي الصحيح -صحيح مسلم- عن جندب بن عبد الله البجلي  عن النبي ﷺ أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد.. ألا فلا تتخذوا القبور مساجد فإني أنهاكم عن ذلك وهذا نهي عظيم لوجوه ثلاثة: أولًا: ذم من فعل ذلك من اليهود والنصارى وغيرهم، وهذا تحذير من التشبه بهم. الثاني: قوله: فلا تتخذوا القبور مساجد هذا نهي صريح لا تتخذوا القبور مساجد. الثالث: قوله: فإني أنهاكم عن ذلك فهذا - أيضًا - تأكيد للنهي بقوله: فإني أنهاكم عن ذلك. فالواجب الحذر، والسر في هذا - والله أعلم - كما هو معروف عند أهل العلم أنه ذريعة للشرك، أن هذا البناء، وهذا التصوير عليها من أسباب الشرك بها، واتخاذ أهلها آلهة مع الله، كما قد وقع لليهود والنصارى وغيرهم، فيجب الحذر من ذلك، وألا يبنى على القبر لا مسجد ولا غيره، ولا قبة ولا غيرها، ولا يدعى من دون الله ولا يستغاث، ولا يطاف، إلى غير ذلك. العبادة حق الله وحده، هو الذي يدعى ويرجى، ويصلى له، ويسجد له، وينذر له، ويذبح له قال تعالى: قُلْ إِنَّ صَلاتِي[الأنعام:162] يعني: قل يا محمد للناس: إِنَّ صَلاتِي وَنُسُكِي[الأنعام:162] يعني: ذبحي وعباداتي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ[الأنعام:162-163] هكذا أمره الله أن يبلغ الناس عليه الصلاة والسلام. وقال تعالى: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ[الكوثر:1-2] وقال تعالى: ثُمَّ لْيَقْضُوا تَفَثَهُمْ وَلْيُوفُوا نُذُورَهُمْ وَلْيَطَّوَّفُوا بِالْبَيْتِ الْعَتِيقِ[الحج:29] الطواف بالبيت العتيق، ما يطاف بالقبور، الطواف بالقبور عبادة لها من دون الله، وشرك بالله  فإذا طاف يتقرب إلى الميت بالطواف أو يصلي له، أو يسجد له، أو يقول: يا سيدي أغثني، أو انصرني، أو اشف مريضي أو أنا في جوارك؛ كل هذا شرك بالله، كل هذا عبادة لغيره  فالواجب الحذر غاية الحذر، نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18154/حكم-رفع-القبور-لدفن-اكثر-من-ميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_793/nour_79306.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19021,"question":"الرسالة التالية رسالة المستمع علي محمد الخشان من الرياض أخونا يقول: نرى كثيرًا من الناس عند دفن الميت يرفعونه أكثر من شبر وإذا نهيتهم قالوا: إن ذلك وقاية له من السيل، كذلك أراهم يزيدون حصباء فوق القبر بعد الدفن زيادة على ترابه الأصلي، كذلك يرشون عليه ماء، فما حكم ما يفعلون؟","title":"حكم رفع القبر أكثر من شبر وقاية له","answer":"الجواب: كل هذا لا بأس به، الأفضل شبر وما حوله، وإذا زاد يسيرا بالحصباء أو نحوه فالأمر سهل في هذا؛ حتى تعلم القبور وتعرف، وحتى لا تمتهن فإذا دفنوه بترابه وجعلوا الحصباء؛ حتى تثبت التراب ويبقى، ويرش بالماء؛ حتى يبقى هذا لا بأس به، حفظا لترابه وبقاء له.. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18189/حكم-رفع-القبر-اكثر-من-شبر-وقاية-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_927/nour_92706.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19160,"question":"هل يصح بناء القبور من الطوب والأسمنت والحديد؟","title":"حكم بناء القبور من الطوب وغيره","answer":"الجواب: لا يجوز بناء القبور، بل تحفر ولا تبنى؛ لأنه ثبت عن رسول الله عليه الصلاة والسلام أنه نهى عن بناء القبور، نهى عن تجصيصها وعن البناء عليها. ولكن يحفر في الأرض، ويدفن الميت فيه يجعل فيه لحد في جهة القبلة بقدر الميت، ويكون القبر عميقًا بقدر نصف الرجل، حتى يكون بعيدًا عن السباع والكلاب، ويكون أبعد عن الروائح الكريهة التي قد تخرج من القبر، وإذا دعت الضرورة إلى بناء، إذا دعت الضرورة بأن كانت الأرض صلبة ولا يستطيعون الحفر وليس عندهم أرض يحفرون فيها، فلا مانع من جعله بين الأحجار يجمع له أحجار، ويجمع بينها ثم يوضع فوقه ألواح أو غيرها حتى تستره عن السباع وعن الكلاب ونحو ذلك، ويوضع عليها أحجار تستره عن ذلك حسب الطاقة، من دون حاجة إلى بناء، إنما أحجار تضبط بالطين أو بالجص أو بغير ذلك، حتى لا يتصل به الكلاب ونحو ذلك. نعم. المقدم: جزاكم الله خيرًا. الشيخ: عند الضرورة. المقدم: عند الضرورة. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18334/حكم-بناء-القبور-من-الطوب-وغيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_932/nour_93204.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19327,"question":"أخونا يسأل أيضًا ويقول: كثير من الناس يبنون على القبور بالطابون، والبناء لا يكون مرتفعًا، بل يكون ارتفاعه شبرين أو ثلاثة أشبار، هل هذا البناء محرم؟","title":"حكم ارتفاع القبر شبرين أو ثلاثة","answer":"الجواب: نعم، نعم الرسول ﷺ نهى عن البناء على القبور، ونهى عن اتخاذ المساجد عليها؛ لأنه وسيلة إلى الغلو فيها والشرك وتعظيمها، فلا يجوز للمسلم أن يبني على القبور، لا مسجدًا ولا غيره، ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد رواه الشيخان البخاري ومسلم في الصحيحين. وروى مسلم في صحيحه عن جندب بن عبد الله البجلي  عن النبي عليه الصلاة والسلام أنه قال: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد، ألا فلا تتخذوا القبور مساجد؛ فإني أنهاكم عن ذلك رواه مسلم في الصحيح. فالرسول ﷺ نهى عن اتخاذ القبور مساجد، وأخبر أنه من عمل الماضين الذين ذمهم الله وعابهم، وأخبر أنه ينهى عن هذا عليه الصلاة والسلام، وقد وقع في الناس الشرك بسبب هذه الأبنية، وهذه المساجد؛ ولهذا لعن ﷺ من اتخذها؛ لأنها وسيلة للشرك وعبادة المخلوقين من دون الله. وفي الصحيح عن جابر بن عبد الله الأنصاري  وعن أبيه، قال: نهى رسول الله ﷺ أن يجصص القبر، وأن يقعد عليه، وأن يبنى عليه فأخبر جابر  أن الرسول ﷺ نهى عن تجصيص القبور وعن القعود عليها وعن البناء عليها، وهذا صريح في تحريم ذلك. فالبناء على القبر محرم وهكذا القعود عليه وهكذا تجصيصه؛ لأنه وسيلة إلى الغلو فيه، ثم إلى عبادته من دون الله، ولا حول ولا قوة إلا بالله كما جرى لليهود والنصارى، وكما جرى للغلاة من هذه الأمة الذين بنوا على القبور وعظموها حتى عبدت من دون الله، وحتى صارت آلهة تعبد مع الله، كما قد وقع مثل ذلك عند قبر الحسين بن علي  في مصر، وعند قبر البدوي، وعند قبر الجيلاني في العراق، وعند قبور كثيرة. حتى فعله بعض الجهلة عند قبر النبي ﷺ في المدينة لجهلهم لما رأوا أنه مبني عليه، وعليه قبة، ظنوا أن هذا مما يسبب لهم الدعاء، والرسول ﷺ إنما دفن في حجرته في بيت عائشة لم يبن عليه إنما دفن في بيت عائشة في حجرتها رضي الله عنها خوفًا أن يغلو فيه الناس إذا جعل في البقيع بارزًا عند الناس، فدفن في بيتها رضي الله عنها وأرضاها، ثم وضع القبة على الحجرة بعض الأمراء المتأخرين في المدينة قبل الدولة السعودية. فالحاصل: أن البناء على القبور لا يجوز، وهو من وسائل الشرك سواء كان البناء مسجدًا أو غير مسجد، أو قبة تبنى عليه، كل ذلك لا يجوز، والواجب أن تكون القبور ضاحية بارزة في المقابر كما كان الحال على ذلك في عهده ﷺ في البقيع وفي غير البقيع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18531/حكم-ارتفاع-القبر-شبرين-او-ثلاثة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89602.mp3","categories":["نواقض الإسلام","أحكام المقابر"]},{"id":19381,"question":"ما هو القبر الشرعي في الإسلام؟ وهل يجوز أن يرتفع القبر عن الأرض؟ أو يوضع عليه لوحات رخامية؟ أو يلحق به غرف للجلوس عند القبر؟","title":"حكم الكتابة على القبور والبناء عليها","answer":"الجواب: تقدم إيضاح القبر الشرعي، تقدم إيضاحه، ولا يجوز أن يوضع عليه لوحات مكتوب عليها شيء ولا أن يكتب عليه؛ لأن الرسول ﷺ نهى عن الكتابة على القبور لا في لوحات، ولا في غيرها، ونهى عن البناء عليها وعن تجصيصها، لا تجصص ولا يبنى عليها، ولا يوضع عليها لوحات ولا كتابات. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18603/حكم-الكتابة-على-القبور-والبناء-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73921.mp3","categories":["نواقض الإسلام","أحكام المقابر"]}]
